  async function fetchJson(path, options = {}) {
    const {
      timeoutMs = 180000,
      signal: externalSignal,
      ...fetchOptions
    } = options

    const controller = new AbortController()
    const timeout = window.setTimeout(() => controller.abort(), timeoutMs)

    if (externalSignal) {
      if (externalSignal.aborted) controller.abort()
      else externalSignal.addEventListener("abort", () => controller.abort(), { once: true })
    }

    try {
      const response = await fetch(`${API}${path}`, {
        ...fetchOptions,
        signal: controller.signal
      })

      if (!response.ok) {
        let detail = ""
        try {
          const contentType = response.headers.get("content-type") || ""
          if (contentType.includes("application/json")) {
            const payload = await response.json()
            detail = payload?.detail || payload?.technical_detail || payload?.message || payload?.error || ""
          } else {
            detail = (await response.text()).trim()
          }
        } catch {}
        const suffix = detail ? ` — ${String(detail).slice(0, 500)}` : ""
        throw new Error(`${path} failed with HTTP ${response.status}${suffix}`)
      }

      try {
        return await response.json()
      } catch {
        throw new Error(`${path} returned a non-JSON response`)
      }
    } catch (error) {
      if (error?.name === "AbortError") {
        throw new Error(`${path} timed out after ${Math.round(timeoutMs / 1000)} seconds`)
      }
      throw error
    } finally {
      window.clearTimeout(timeout)
    }
  }

  function softTimeout(promise, milliseconds, fallback = null) {
    return Promise.race([
      promise,
      new Promise(resolve => {
        setTimeout(() => resolve(fallback), milliseconds)
      })
    ])
  }


  function isDashboardDataUsable(payload) {
    if (!payload) return false

    const statsPayload = payload.statsData || {}
    const savedVideoPayload = payload.savedVideosData || {}
    const rankingPayload = payload.rankingsData || {}
    const revenuePayload = payload.revenueSummaryData || {}

    const subscribers = Number(statsPayload.subscribers || 0)
    const totalViews = Number(statsPayload.total_views || 0)
    const savedVideoCount = Number((savedVideoPayload.saved_videos || []).length || 0)
    const rankingCount = Number((rankingPayload.player_rankings || []).length || 0)
    const revenueTotal = Number(
      revenuePayload?.summary?.channel_by_period?.lifetime ??
      revenuePayload?.summary?.total_channel_youtube_revenue ??
      0
    )

    return subscribers > 0 || totalViews > 0 || savedVideoCount > 0 || rankingCount > 0 || revenueTotal > 0
  }

  function isFullBootPayloadReady(payload) {
    if (!payload || !isDashboardDataUsable(payload)) return false

    const requiredObjects = [
      payload.revenueSummaryData?.summary,
      payload.youtubeRevenueStatusData?.status,
      payload.revenueForecastData,
      payload.channelBrainData?.channel_brain,
      payload.strategyResponseData,
      payload.deadRecoveryResponseData,
      payload.endScreenData,
      payload.studioIntelligenceData,
      payload.contentStudioStatusData,
      payload.videoEditorStatusData,
      payload.thumbnailBuilderProjectsData,
      payload.thumbnailBuilderSettingsData?.settings,
      payload.communityData,
      payload.clipFinderConfigData,
      payload.clipFinderProjectsData,
      payload.featureReadinessData
    ]

    return requiredObjects.every(value => value !== null && value !== undefined)
  }

  function updateBootItem(key, status, details = {}) {
    const prev = initialBootItemsRef.current || []
    const existing = prev.find(item => item.key === key)
    if (!existing) return

    // Polling responses can arrive after a request has completed. Terminal
    // states are final so one late response can never move a task backward.
    const terminalStatuses = ["done", "warning", "error"]
    if (terminalStatuses.includes(existing.status) && status === "running") return

    const normalizedProgress = details.progress === undefined
      ? undefined
      : Math.max(0, Math.min(100, Number(details.progress || 0)))
    const nextLabel = String(details.label || details.message || "").trim()

    if (
      existing.status === status &&
      (normalizedProgress === undefined || Number(existing.running_progress || 0) === normalizedProgress) &&
      (!nextLabel || existing.active_label === nextLabel)
    ) return

    const completedCount = prev.filter(item => ["done", "warning"].includes(item.status)).length
    const now = Date.now()

    if (["done", "warning"].includes(status) && existing.started_at) {
      saveTaskEstimateMs(key, now - Number(existing.started_at), existing.default_ms || existing.expected_ms)
    }

    const next = prev.map(item => {
      if (item.key !== key) return item

      return {
        ...item,
        status,
        running_progress: ["done", "warning"].includes(status)
          ? 100
          : (normalizedProgress === undefined ? Number(item.running_progress || 0) : normalizedProgress),
        active_label: nextLabel || item.active_label || "",
        started_at: status === "running" ? (item.started_at || now) : item.started_at,
        completed_at: ["done", "warning"].includes(status) ? now : item.completed_at,
        completion_order: ["done", "warning"].includes(status)
          ? (item.completion_order || completedCount + 1)
          : item.completion_order
      }
    })

    initialBootItemsRef.current = next
    setInitialBootRequiredItems(next)
    setInitialBootCompletedUnits(next.filter(item => ["done", "warning"].includes(item.status)).length)
    setInitialBootTotalUnits(next.length)
  }

