  function startBootStatusPolling(taskKey, statusPath) {
    let stopped = false
    let requestInFlight = false

    const poll = async () => {
      if (stopped || requestInFlight) return
      requestInFlight = true

      try {
        const status = await fetchJson(statusPath, { timeoutMs: 5000 })
        if (stopped) return

        const progress = Math.min(95, Math.max(0, Number(status?.progress || 0)))
        const message = String(status?.message || "").trim()

        updateBootItem(taskKey, "running", {
          progress,
          message
        })
      } catch {
        // The main sync request remains the source of success or failure.
        // A missed status poll must never fail startup by itself.
      } finally {
        requestInFlight = false
      }
    }

    const firstPollTimer = window.setTimeout(poll, 250)
    const timer = window.setInterval(poll, 300)

    return () => {
      stopped = true
      window.clearTimeout(firstPollTimer)
      window.clearInterval(timer)
    }
  }

  async function runFullAutoSync({ boot = false } = {}) {
    if (autoSyncInFlightRef.current) return

    autoSyncInFlightRef.current = true
    setAutoSyncingAll(true)

    try {
      if (boot) {
        const bootNow = Date.now()
        const bootItems = createStartupTasks()

        initialBootStartedAtRef.current = bootNow
        initialBootTargetPercentRef.current = 1
        initialBootDisplayPercentRef.current = 1

        initialBootItemsRef.current = bootItems
        setInitialBootRequiredItems(bootItems)
        setInitialBootProgress(1)
        setInitialBootDisplayProgress(1)
        setInitialBootCompletedUnits(0)
        setInitialBootTotalUnits(bootItems.length)
        setInitialBootRemainingSeconds(null)
        setInitialBootSyncComplete(false)
        setInitialBootError("")
        setInitialBootPhase("starting")
        setInitialBootStep("Connecting to CourtVision AI...")

        updateBootItem("backendReady", "running")

        // The root route only responds after the backend and database are ready.
        await fetchJson("/", { timeoutMs: 30000 })

        updateBootItem("backendReady", "done")
        updateBootItem("cachedData", "running")
        setInitialBootStep("Loading saved CourtVision data...")

        // Keep this phase intentionally lightweight. The old version called
        // /dashboard/startup-data here, which loaded nearly every tab before
        // the real sync and then loaded all of it again afterward.
        const cachedStats = await fetchJson("/dashboard/stats", {
          timeoutMs: 30000
        })
        setStats(cachedStats || {})

        updateBootItem("cachedData", "done")
      }

      if (boot) {
        setInitialBootPhase("video")
        updateBootItem("dashboardSync", "running")
        setInitialBootStep("Refreshing YouTube videos and channel statistics...")
      }

      if (boot) {
        // Startup is data-first: saved database state makes tabs usable now,
        // while remote YouTube refreshes continue without holding the loader.
        updateBootItem("dashboardSync", "warning", {
          label: "Saved video and channel data ready; refresh continuing in background"
        })
        updateBootItem("revenueSync", "warning", {
          label: "Saved Analytics data ready; refresh continuing in background"
        })

        Promise.allSettled([
          fetchJson("/dashboard/auto-sync", { method: "POST", timeoutMs: 240000 }),
          fetchJson("/revenue/youtube/auto-sync", { method: "POST", timeoutMs: 300000 })
        ]).then(() => {
          // Refresh visible data once both background jobs settle. This is
          // intentionally non-blocking and deduplicated by runFullAutoSync.
          loadData().catch(() => {})
        })
      } else {
        const dashboardSyncResult = await fetchJson("/dashboard/auto-sync", {
          method: "POST",
          timeoutMs: 240000
        })
        if (dashboardSyncResult?.ok === false) {
          throw new Error(dashboardSyncResult?.message || dashboardSyncResult?.error || "Dashboard/video sync failed.")
        }

        const revenueSyncResult = await fetchJson("/revenue/youtube/auto-sync", {
          method: "POST",
          timeoutMs: 300000
        })
        if (revenueSyncResult?.ok === false || revenueSyncResult?.revenue_sync?.ok === false) {
          throw new Error(revenueSyncResult?.message || revenueSyncResult?.revenue_sync?.message || revenueSyncResult?.error || "Revenue sync failed.")
        }
      }

      if (boot) {
        setInitialBootPhase("data")
        setInitialBootStep("Loading saved data and verifying every CourtVision feature...")
      }

      const loadedPayload = boot
        ? await loadDataPayloadWithBootTracking()
        : await loadDataPayload()

      applyLoadedData(loadedPayload)

      if (boot) {
        updateBootItem("finalVerification", "running", {
          label: "Verifying every required tab is ready...",
          progress: 30
        })

        updateBootItem("finalVerification", "running", {
          label: "Checking required tab payloads...",
          progress: 58
        })

        if (!isFullBootPayloadReady(loadedPayload)) {
          const requiredChecks = {
            dashboard: isDashboardDataUsable(loadedPayload),
            revenueSummary: loadedPayload?.revenueSummaryData?.summary != null,
            youtubeRevenueStatus: loadedPayload?.youtubeRevenueStatusData?.status != null,
            revenueForecast: loadedPayload?.revenueForecastData != null,
            decisionEngine: loadedPayload?.channelBrainData?.channel_brain != null,
            strategyIntelligence: loadedPayload?.strategyResponseData != null,
            deadVideoRecovery: loadedPayload?.deadRecoveryResponseData != null,
            endScreenOptimizer: loadedPayload?.endScreenData != null,
            studioIntelligence: loadedPayload?.studioIntelligenceData != null,
            contentStudioStatus: loadedPayload?.contentStudioStatusData != null,
            videoEditorStatus: loadedPayload?.videoEditorStatusData != null,
            thumbnailBuilderProjects: loadedPayload?.thumbnailBuilderProjectsData != null,
            thumbnailBuilderSettings: loadedPayload?.thumbnailBuilderSettingsData?.settings != null,
            communityAutomation: loadedPayload?.communityData != null,
            clipFinderConfiguration: loadedPayload?.clipFinderConfigData != null,
            clipFinderProjects: loadedPayload?.clipFinderProjectsData != null,
            sharedFeatureReadiness: loadedPayload?.featureReadinessData?.ok === true
          }
          const missingSections = Object.entries(requiredChecks)
            .filter(([, ready]) => !ready)
            .map(([name]) => name)

          updateBootItem("finalVerification", "error", {
            label: `Required tab verification failed: ${missingSections.join(", ") || "unknown section"}`
          })
          throw new Error(
            `Required CourtVision sections did not finish loading: ${missingSections.join(", ") || "unknown section"}.`
          )
        }

        updateBootItem("finalVerification", "running", {
          label: "Applying verified data to every tab...",
          progress: 82
        })

        // Give React two paint cycles to apply every loaded payload before the
        // loading screen is allowed to disappear. This prevents tabs such as
        // Decision Engine from briefly rendering their own loading message.
        await new Promise(resolve => window.requestAnimationFrame(() =>
          window.requestAnimationFrame(resolve)
        ))

        updateBootItem("finalVerification", "running", {
          label: "Final readiness check...",
          progress: 96
        })
        await new Promise(resolve => window.requestAnimationFrame(resolve))
        updateBootItem("finalVerification", "done")
      }

      setLastAutoSync(new Date())

      if (boot) {
        setInitialBootStep("CourtVision AI is ready.")
        setInitialBootRemainingSeconds(0)
        setInitialBootSyncComplete(true)
      }
    } catch (error) {
      console.error("CourtVision auto-sync failed:", error)

      if (boot) {
        const failedTasks = (initialBootItemsRef.current || [])
          .filter(item => item.status === "error")
          .map(item => `${item.label}${item.active_label ? `: ${item.active_label}` : ""}`)
        const baseMessage = error?.message ||
          "CourtVision could not connect to the backend. Make sure backend port 8001 is running."
        const startupMessage = failedTasks.length
          ? `${baseMessage}\n\nFailed startup checks:\n${failedTasks.map(task => `• ${task}`).join("\n")}`
          : baseMessage

        const runningTask = (initialBootItemsRef.current || []).find(item => item.status === "running")
        if (runningTask) {
          updateBootItem(runningTask.key, "error", {
            label: `${runningTask.label} failed`
          })
        }

        setInitialBootError(startupMessage)
        setShowBootTechnicalDetails(false)
        setInitialBootStep("CourtVision could not finish startup.")
        setInitialBootRemainingSeconds(0)
        setInitialBootSyncComplete(false)
      }
    } finally {
      autoSyncInFlightRef.current = false
      setAutoSyncingAll(false)
    }
  }

  useEffect(() => {
    if (!initialBootLoading) return

    const progressTimer = window.setInterval(() => {
      const now = Date.now()
      const currentItems = initialBootItemsRef.current || []
      const items = currentItems.map(item => {
        if (item.status !== "running" || !item.started_at) return item
        const expectedMs = Math.max(800, Number(item.expected_ms || item.default_ms || 8000))
        const elapsedMs = Math.max(0, now - Number(item.started_at))
        const timedProgress = Math.min(94, (elapsedMs / expectedMs) * 88)
        const nextProgress = Math.max(Number(item.running_progress || 0), timedProgress)
        return Math.abs(nextProgress - Number(item.running_progress || 0)) >= 0.15
          ? { ...item, running_progress: Number(nextProgress.toFixed(2)) }
          : item
      })
      if (items.some((item, index) => item !== currentItems[index])) {
        initialBootItemsRef.current = items
        setInitialBootRequiredItems(items)
      }
      const snapshot = computeStartupSnapshot(items, {
        syncComplete: initialBootSyncComplete,
        workerCount: STARTUP_WORKER_COUNT
      })

      initialBootTargetPercentRef.current = Math.max(
        Number(initialBootTargetPercentRef.current || 0.5),
        snapshot.rawPercent
      )

      if (!initialBootSyncComplete && snapshot.activeItem) {
        const activeLabel = String(
          snapshot.activeItem.active_label ||
          snapshot.activeItem.label ||
          "Loading CourtVision data"
        ).replace(/\.\.\.$/, "")
        setInitialBootStep(`${activeLabel}...`)
      }

      const target = Number(initialBootTargetPercentRef.current || 0.5)
      setInitialBootDisplayProgress(currentValue => {
        const current = Number(currentValue || 0.5)
        if (target <= current) return current

        const gap = target - current
        // Never teleport to a newly verified checkpoint. Catch up quickly when
        // far behind and ease into the target when close. Even the final move
        // to 100% is visible and smooth, while adding less than ~2 seconds.
        const maxStep = initialBootSyncComplete ? 3.2 : 2.35
        const minStep = initialBootSyncComplete ? 0.7 : 0.22
        const proportionalStep = gap * (initialBootSyncComplete ? 0.20 : 0.16)
        const step = Math.min(maxStep, Math.max(minStep, proportionalStep))
        const next = Math.min(target, current + Math.min(step, gap))
        initialBootDisplayPercentRef.current = next
        return next
      })

      const displayedNow = Number(initialBootDisplayPercentRef.current || 0.5)
      const visualCatchupSeconds = initialBootSyncComplete && displayedNow < 99.95
        ? Math.max(1, Math.ceil((100 - displayedNow) / 18))
        : 0

      const nextRemainingSeconds = Math.max(snapshot.remainingSeconds, visualCatchupSeconds)

      setInitialBootProgress(snapshot.rawPercent)
      setInitialBootCompletedUnits(snapshot.completedCount)
      setInitialBootTotalUnits(snapshot.totalCount)
      setInitialBootRemainingSeconds(currentValue => {
        if (currentValue === null || currentValue === undefined) return nextRemainingSeconds
        if (nextRemainingSeconds === 0) return 0

        const current = Math.max(0, Number(currentValue || 0))
        const difference = nextRemainingSeconds - current
        if (Math.abs(difference) <= 2) return nextRemainingSeconds

        // ETA can correct itself as tasks finish, but it should not flash from
        // minutes to seconds in one frame or jump upward dramatically.
        const adjustment = difference < 0
          ? Math.max(-5, difference * 0.28)
          : Math.min(2, difference * 0.18)
        return Math.max(1, Math.round(current + adjustment))
      })
    }, 160)

    return () => window.clearInterval(progressTimer)
  }, [initialBootLoading, initialBootSyncComplete])



  useEffect(() => {
    if (
      !initialBootLoading ||
      initialBootError ||
      !initialBootSyncComplete ||
      initialBootDisplayProgress < 99.95
    ) return

    setInitialBootRemainingSeconds(0)
    setInitialBootPhase("complete")
    setInitialBootStep("CourtVision AI Ready.")

    const dashboardTimer = setTimeout(() => {
      const totalMs = initialBootStartedAtRef.current
        ? Date.now() - Number(initialBootStartedAtRef.current)
        : 0
      saveStartupDiagnostics(initialBootItemsRef.current || [], totalMs)
      setInitialBootLoading(false)
    }, 120)

    return () => clearTimeout(dashboardTimer)
  }, [
    initialBootLoading,
    initialBootError,
    initialBootSyncComplete,
    initialBootDisplayProgress
  ])


  useEffect(() => {
    if (!initialBootStartedRef.current) {
      initialBootStartedRef.current = true
      runFullAutoSync({ boot: true })
    }

    const liveDataTimer = setInterval(() => {
      loadData().catch(() => {})
    }, 60000)

    const fullSyncTimer = setInterval(() => {
      runFullAutoSync().catch(() => {})
    }, 900000)

    return () => {
      clearInterval(liveDataTimer)
      clearInterval(fullSyncTimer)
    }
  }, [])

