  function updatePlayerSearch(value) {
    setPlayerSearch(value)
    setPrediction(null)

    const query = value.trim()

    if (!query) {
      setPlayerResults([])
      return
    }

    fetch(`${API}/player-predictor/search?q=${encodeURIComponent(query)}`)
      .then(r => r.json())
      .then(d => {
        const sortedResults = (d.results || [])
          .map(player => typeof player === "string" ? { name: player } : player)
          .filter(player => player?.name)
          .sort((a, b) => String(a.name).localeCompare(String(b.name)))

        setPlayerResults(sortedResults)
      })
      .catch(() => setPlayerResults([]))
  }

  function selectPlayerResult(name) {
    setPlayerSearch(name)
    setPlayerResults([])
    setPrediction(null)
  }

  function runPlayerPrediction() {
    const name = playerSearch.trim()

    if (!name) return

    setPlayerResults([])

    fetch(
      `${API}/revenue-simulator?name=${encodeURIComponent(name)}&video_length=3&title_type=${encodeURIComponent(playerFormat)}`
    )
      .then(r => r.json())
      .then(d => {
        if (d.found && d.simulation) {
          setPrediction({
            ...d.simulation,
            name: d.simulation.name || name,
            selected_format: playerFormat
          })
          return
        }

        return fetch(`${API}/player-predictor/predict?name=${encodeURIComponent(name)}`)
          .then(r => r.json())
          .then(fallback => {
            if (fallback.found && fallback.prediction) {
              setPrediction({
                ...fallback.prediction,
                name: fallback.prediction.name || name,
                selected_format: playerFormat
              })
            }
          })
      })
      .catch(() => {})
  }


  function uploadContentStudioProject() {
    if (!contentStudioFiles.length) {
      showCourtVisionDialog("Choose at least one MP4 file first.")
      return
    }

    if (contentStudioProjectType === "solo" && contentStudioFiles.length !== 1) {
      showCourtVisionDialog("Solo Highlight projects need exactly 1 MP4 file. Use Top 10 Countdown if you want to upload one long source or multiple clips.")
      return
    }

    if (contentStudioProjectType === "top10" && contentStudioFiles.length < 1) {
      showCourtVisionDialog("Top 10 Countdown needs at least 1 MP4 file. You can upload one long source video or multiple individual clips.")
      return
    }

    const formData = new FormData()
    formData.append("project_type", contentStudioProjectType)
    formData.append(
      "project_name",
      contentStudioProjectName.trim() ||
        (contentStudioProjectType === "top10" ? "Untitled Top 10 Project" : "Untitled Solo Highlight")
    )

    Array.from(contentStudioFiles).forEach(file => {
      formData.append("files", file)
    })

    setContentStudioUploading(true)

    fetch(`${API}/content-studio/upload`, {
      method: "POST",
      body: formData
    })
      .then(async r => {
        const data = await r.json()

        if (!r.ok) {
          showCourtVisionDialog("Content Studio upload failed: " + JSON.stringify(data))
          return
        }

        setContentStudioActiveProject(data.project || null)
        setContentStudioProjectName("")
        setContentStudioFiles([])
        loadContentStudioData()
        showCourtVisionDialog("Content Studio project created.")
      })
      .catch(err => {
        showCourtVisionDialog("Content Studio upload failed: " + err.message)
      })
      .finally(() => setContentStudioUploading(false))
  }

  async function openContentStudioProject(projectId) {
    try {
      const response = await fetch(`${API}/content-studio/project/${projectId}`, { cache: "no-store" })
      const data = await response.json().catch(() => null)

      if (!response.ok || !data?.found || !data?.project) {
        throw new Error(data?.message || data?.detail || `Project request failed (${response.status}).`)
      }

      const serverProject = data.project
      const localProject = readContentStudioLocalDraft(projectId)
      const serverClips = Array.isArray(serverProject?.clips) ? serverProject.clips : []
      const localClips = Array.isArray(localProject?.clips) ? localProject.clips : []
      const serverUpdated = Date.parse(serverProject?.updated_at || "") || 0
      const localUpdated = Number(localProject?._local_saved_at || 0)

      const useLocal = !!localProject &&
        localProject.project_id === serverProject.project_id &&
        localClips.length > 0 &&
        (localClips.length > serverClips.length || localUpdated > serverUpdated)

      const openedProject = useLocal
        ? { ...serverProject, ...localProject, clips: localClips.map(clip => ({ ...clip })) }
        : serverProject

      contentStudioLatestProjectRef.current = openedProject
      setContentStudioActiveProject(openedProject)
      setContentStudioSelectedClipId(openedProject.clips?.[0]?.clip_id || null)
      setContentStudioPlayheadSeconds(0)
      setContentStudioShowTrash(false)

      if (useLocal) {
        window.setTimeout(() => persistContentStudioProject(openedProject, { keepalive: false }), 0)
      } else {
        storeContentStudioLocalDraft(openedProject)
      }
    } catch (error) {
      showCourtVisionDialog("The selected project could not be opened.", {
        title: "Project Could Not Open",
        type: "error",
        resolution: "Refresh the project list and try again. If the issue continues, confirm the backend is running and the project file still exists.",
        technicalDetail: error?.message || String(error)
      })
    }
  }

  function loadContentStudioTrash() {
    fetch(`${API}/content-studio/trash`, { cache: "no-store" })
      .then(response => response.json())
      .then(data => setContentStudioTrashProjects(Array.isArray(data.projects) ? data.projects : []))
      .catch(() => setContentStudioTrashProjects([]))
  }

  function restoreContentStudioProject(projectId) {
    fetch(`${API}/content-studio/project/${projectId}/restore`, { method: "POST" })
      .then(response => response.json())
      .then(() => {
        loadContentStudioData()
        loadContentStudioTrash()
      })
  }

  function permanentlyDeleteContentStudioProject(projectId) {
    showCourtVisionConfirm(
      "Permanently delete this project and all source clips, renders, and thumbnails?",
      {
        title: "Permanently Delete Project",
        confirmLabel: "Delete Forever",
        onConfirm: () => {
          fetch(`${API}/content-studio/project/${projectId}/permanent`, { method: "DELETE" })
            .then(response => response.json())
            .then(() => loadContentStudioTrash())
            .catch(error => showCourtVisionDialog("The project could not be permanently deleted.", { technicalDetail: error.message }))
        }
      }
    )
  }

  function deleteContentStudioProject(projectId) {
    showCourtVisionConfirm(
      "Move this project to Trash? You can restore it later.",
      {
        title: "Move Project to Trash",
        confirmLabel: "Move to Trash",
        onConfirm: async () => {
          try {
            const response = await fetch(`${API}/content-studio/project/${projectId}/trash`, {
              method: "POST",
              headers: { "Content-Type": "application/json" }
            })
            const data = await response.json().catch(() => null)

            if (!response.ok || data?.ok === false || !data?.found) {
              throw new Error(data?.message || data?.detail || `Trash request failed (${response.status}).`)
            }

            if (contentStudioActiveProject?.project_id === projectId) {
              setContentStudioActiveProject(null)
            }

            setContentStudioProjects(previous => previous.filter(project => project.project_id !== projectId))
            setContentStudioTrashProjects(previous => {
              const moved = data.project
              if (!moved?.project_id) return previous
              return [moved, ...previous.filter(project => project.project_id !== moved.project_id)]
            })

            await Promise.all([loadContentStudioData(), loadContentStudioTrash()])
          } catch (error) {
            showCourtVisionDialog("The project could not be moved to Trash.", {
              title: "Project Could Not Be Trashed",
              type: "error",
              resolution: "Try again after confirming the backend is running. Your project has not been removed.",
              technicalDetail: error?.message || String(error)
            })
          }
        }
      }
    )
  }


  async function closeContentStudioProject() {
    window.clearTimeout(contentStudioAutosaveTimerRef.current)
    const latest = contentStudioLatestProjectRef.current || contentStudioActiveProject

    if (latest?.project_id) {
      // Wait for every queued edit plus one final newest-state snapshot before
      // leaving. This prevents pasted duplicate clips from disappearing when
      // the project is reopened immediately.
      await persistContentStudioProject(latest, { keepalive: false })
      await contentStudioSaveChainRef.current.catch(() => null)
    }

    setContentStudioActionModalOpen(false)
    setContentStudioActiveProject(null)
    setContentStudioSelectedClipId(null)
    loadContentStudioData()
  }


  function getContentStudioDraft(project = contentStudioActiveProject) {
    if (!project) return null

    return project.project_type === "top10" ? project.top10_draft : project.solo_draft
  }

  function updateContentStudioProjectField(field, value) {
    setContentStudioActiveProject(currentProject => {
      if (!currentProject) return currentProject
      const nextProject = { ...currentProject, [field]: value }
      scheduleContentStudioAutosave(nextProject)
      return nextProject
    })
  }

  function buildContentStudioEditPayload(project) {
    if (!project) return null
    const draft = project.project_type === "top10" ? project.top10_draft : project.solo_draft
    return {
      project_name: project.project_name,
      clips: (project.clips || []).map((clip, index) => ({
        clip_id: clip.clip_id,
        order: index + 1,
        title: clip.title,
        split_from_clip_id: clip.split_from_clip_id || null,
        file_path: clip.file_path || "",
        preview_url: clip.preview_url || "",
        original_filename: clip.original_filename || "",
        trim_start: Number(clip.trim_start || 0),
        trim_end: Number(clip.trim_end || 0),
        duration_seconds: Number(clip.duration_seconds || 0),
        selected_for_top10: !!clip.selected_for_top10,
        frame_x: Number(clip.frame_x || 0),
        frame_y: Number(clip.frame_y || 0),
        frame_scale: Number(clip.frame_scale || 1),
        source_fps: Number(clip.source_fps || 0),
        muted: !!clip.muted,
        playback_rate: getContentStudioClipPlaybackRate(clip),
        blurred_side_fill: !!clip.blurred_side_fill,
        blur_crop_left_pct: Number(clip.blur_crop_left_pct ?? 0),
        blur_crop_right_pct: Number(clip.blur_crop_right_pct ?? 0),
        blur_crop_offset_pct: Number(clip.blur_crop_offset_pct ?? 0)
      })),
      top10_draft: project.project_type === "top10" ? draft : null,
      solo_draft: project.project_type === "solo" ? draft : null,
      render_settings: project.render_settings ? {
        output_fps: Number(project.render_settings.output_fps || 0),
        interpolation_mode: String(project.render_settings.interpolation_mode || "auto")
      } : null
    }
  }

  function getContentStudioLocalDraftKey(projectId) {
    return `courtvision_content_studio_draft_${String(projectId || "")}`
  }

  function storeContentStudioLocalDraft(project) {
    if (!project?.project_id) return
    try {
      const snapshot = {
        ...project,
        clips: (project.clips || []).map(clip => ({ ...clip })),
        _local_saved_at: Date.now()
      }
      window.localStorage.setItem(
        getContentStudioLocalDraftKey(project.project_id),
        JSON.stringify(snapshot)
      )
    } catch (_) {}
  }

  function readContentStudioLocalDraft(projectId) {
    try {
      const raw = window.localStorage.getItem(getContentStudioLocalDraftKey(projectId))
      return raw ? JSON.parse(raw) : null
    } catch (_) {
      return null
    }
  }

  function persistContentStudioProject(project, options = {}) {
    if (!project?.project_id) return Promise.resolve(null)
    const projectSnapshot = {
      ...project,
      clips: (project.clips || []).map(clip => ({ ...clip }))
    }
    contentStudioLatestProjectRef.current = projectSnapshot
    storeContentStudioLocalDraft(projectSnapshot)
    const payload = buildContentStudioEditPayload(projectSnapshot)
    const revision = ++contentStudioSaveRevisionRef.current

    // Serialize writes so an older request can never finish after and overwrite
    // a newer multi-clip timeline. Every queued request contains an immutable
    // snapshot of the exact editor state that existed when it was scheduled.
    const request = () => fetch(`${API}/content-studio/project/${projectSnapshot.project_id}/edit`, {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
        "X-CourtVision-Edit-Revision": String(revision),
        "X-CourtVision-Edit-Session": contentStudioSaveSessionRef.current
      },
      body: JSON.stringify(payload),
      keepalive: !!options.keepalive
    }).then(response => response.ok ? response.json().catch(() => null) : null).catch(() => null)

    contentStudioSaveChainRef.current = contentStudioSaveChainRef.current
      .catch(() => null)
      .then(request)
    return contentStudioSaveChainRef.current
  }

  function detectContentStudioSideFillCrop(video, clipId, options = {}) {
    if (!video || !clipId || !video.videoWidth || !video.videoHeight) return null

    try {
      const sampleWidth = Math.min(960, video.videoWidth)
      const sampleHeight = Math.max(180, Math.round(sampleWidth * video.videoHeight / video.videoWidth))
      const canvas = document.createElement("canvas")
      canvas.width = sampleWidth
      canvas.height = sampleHeight
      const context = canvas.getContext("2d", { willReadFrequently: true })
      if (!context) return null

      context.drawImage(video, 0, 0, sampleWidth, sampleHeight)
      const pixels = context.getImageData(0, 0, sampleWidth, sampleHeight).data
      const sampleRows = [0.08, 0.16, 0.28, 0.40, 0.52, 0.64, 0.76, 0.88, 0.94]
        .map(ratio => Math.max(0, Math.min(sampleHeight - 1, Math.round(sampleHeight * ratio))))

      const columnStats = (x) => {
        let mattePixels = 0
        let veryBlackPixels = 0
        let luminanceSum = 0
        let colorSpreadSum = 0
        for (const y of sampleRows) {
          const i = (y * sampleWidth + x) * 4
          const r = pixels[i]
          const g = pixels[i + 1]
          const b = pixels[i + 2]
          const luminance = (r * 0.2126) + (g * 0.7152) + (b * 0.0722)
          const spread = Math.max(r, g, b) - Math.min(r, g, b)
          luminanceSum += luminance
          colorSpreadSum += spread
          if (luminance <= 58 && spread <= 30) mattePixels += 1
          if (luminance <= 32) veryBlackPixels += 1
        }
        const total = sampleRows.length
        return {
          matteRatio: mattePixels / total,
          blackRatio: veryBlackPixels / total,
          average: luminanceSum / total,
          spread: colorSpreadSum / total
        }
      }

      const isMatteColumn = (x) => {
        const stats = columnStats(x)
        return (
          (stats.matteRatio >= 0.67 && stats.average <= 58 && stats.spread <= 30) ||
          (stats.blackRatio >= 0.56 && stats.average <= 62)
        )
      }

      const maxScan = Math.floor(sampleWidth * 0.39)
      const findBoundary = (fromLeft) => {
        let lastMatteOffset = -1
        let contentRun = 0
        for (let offset = 0; offset < maxScan; offset += 1) {
          const x = fromLeft ? offset : sampleWidth - 1 - offset
          if (isMatteColumn(x)) {
            lastMatteOffset = offset
            contentRun = 0
          } else {
            contentRun += 1
            if (contentRun >= 12) break
          }
        }
        return lastMatteOffset + 1
      }

      let left = findBoundary(true)
      let right = findBoundary(false)
      const minDetected = Math.max(2, Math.floor(sampleWidth * 0.004))
      if (left < minDetected) left = 0
      if (right < minDetected) right = 0

      const history = options.reset ? [] : [...(contentStudioSideFillDetectionRef.current[clipId] || [])]
      history.push({ left, right })
      while (history.length > 8) history.shift()
      contentStudioSideFillDetectionRef.current[clipId] = history

      const stableBoundary = (side) => {
        const values = history.map(item => Number(item[side] || 0)).sort((a, b) => a - b)
        if (!values.length) return 0
        // A bar must survive across multiple decoded frames. The lower-middle
        // percentile rejects a dark gameplay frame that only looks pillarboxed once.
        const index = Math.max(0, Math.min(values.length - 1, Math.floor((values.length - 1) * 0.40)))
        return values[index]
      }

      left = stableBoundary("left")
      right = stableBoundary("right")
      if (!left && !right) {
        const fallback = { leftPct: 0, rightPct: 0, activePct: 100, backgroundScale: 1, centerOffsetPct: 0 }
        setContentStudioSideFillCropByClip(current => ({ ...current, [clipId]: fallback }))
        return fallback
      }

      const safety = Math.max(6, Math.round(sampleWidth * 0.008))
      if (left) left += safety
      if (right) right += safety

      const leftPct = Math.max(0, Math.min(40, (left / sampleWidth) * 100))
      const rightPct = Math.max(0, Math.min(40, (right / sampleWidth) * 100))
      const activePct = Math.max(28, 100 - leftPct - rightPct)
      const detectedCrop = {
        leftPct,
        rightPct,
        activePct,
        backgroundScale: Math.min(4, Math.max(1, 100 / activePct)),
        centerOffsetPct: (rightPct - leftPct) / 2
      }
      setContentStudioSideFillCropByClip(current => {
        const previous = current[clipId]
        if (previous && Math.abs(previous.leftPct - leftPct) < 0.08 && Math.abs(previous.rightPct - rightPct) < 0.08) return current
        return { ...current, [clipId]: detectedCrop }
      })
      return detectedCrop
    } catch (_) {
      return null
    }
  }

  function drawContentStudioSideFillBackground(video, clip = null) {
    const canvas = contentStudioPreviewBackgroundCanvasRef.current
    const activeClip = clip || getContentStudioSelectedClip()
    if (!canvas || !video || !activeClip?.blurred_side_fill || !video.videoWidth || !video.videoHeight) return

    const width = Math.max(2, Math.round(canvas.clientWidth || 640))
    const height = Math.max(2, Math.round(canvas.clientHeight || 360))
    if (canvas.width !== width) canvas.width = width
    if (canvas.height !== height) canvas.height = height

    const detected = contentStudioSideFillCropByClip[activeClip.clip_id] || {}
    const leftPct = Number(activeClip.blur_crop_left_pct ?? detected.leftPct ?? 0)
    const rightPct = Number(activeClip.blur_crop_right_pct ?? detected.rightPct ?? 0)
    const sourceWidth = Number(video.videoWidth || 0)
    const sourceHeight = Number(video.videoHeight || 0)
    const cropX = Math.max(0, Math.min(sourceWidth - 2, sourceWidth * leftPct / 100))
    const cropRight = Math.max(0, Math.min(sourceWidth - cropX - 2, sourceWidth * rightPct / 100))
    const cropWidth = Math.max(2, sourceWidth - cropX - cropRight)
    const scale = Math.max(width / cropWidth, height / sourceHeight)
    const drawWidth = cropWidth * scale
    const drawHeight = sourceHeight * scale
    const context = canvas.getContext('2d', { alpha: false })
    if (!context) return
    context.clearRect(0, 0, width, height)
    context.drawImage(video, cropX, 0, cropWidth, sourceHeight, (width - drawWidth) / 2, (height - drawHeight) / 2, drawWidth, drawHeight)
  }

  function setContentStudioTwoTrackTime(sourceTime) {
    const foregroundVideo = contentStudioPreviewRef.current
    const backgroundVideo = contentStudioPreviewBackgroundVideoRef.current
    const targetTime = Math.max(0, Number(sourceTime || 0))
    for (const media of [foregroundVideo, backgroundVideo]) {
      if (!media) continue
      try { media.currentTime = targetTime } catch (_) {}
    }
  }

  function pauseContentStudioTwoTracks() {
    const foregroundVideo = contentStudioPreviewRef.current
    const backgroundVideo = contentStudioPreviewBackgroundVideoRef.current
    for (const media of [foregroundVideo, backgroundVideo]) {
      if (!media) continue
      try { media.pause() } catch (_) {}
    }
  }

  function waitForContentStudioSeek(media, targetTime) {
    if (!media) return Promise.resolve()
    const target = Math.max(0, Number(targetTime || 0))
    const tolerance = 0.008
    if (!media.seeking && Math.abs(Number(media.currentTime || 0) - target) <= tolerance) return Promise.resolve()
    return new Promise((resolve) => {
      let settled = false
      const finish = () => {
        if (settled) return
        settled = true
        media.removeEventListener('seeked', finish)
        window.clearTimeout(timeout)
        resolve()
      }
      const timeout = window.setTimeout(finish, 1500)
      media.addEventListener('seeked', finish, { once: true })
      try { media.currentTime = target } catch (_) { finish() }
    })
  }

  function syncContentStudioSideFillBackground(video, clip = null) {
    drawContentStudioSideFillBackground(video, clip)
  }

  function scheduleContentStudioSideFillBackground(video, clip = null) {
    if (!video) return

    const pending = contentStudioBackgroundFrameCallbackRef.current || {}
    if (pending.video?.cancelVideoFrameCallback && pending.id !== null) {
      try { pending.video.cancelVideoFrameCallback(pending.id) } catch (_) {}
    }
    contentStudioBackgroundFrameCallbackRef.current = { video: null, id: null }

    const drawDecodedFrame = () => {
      if (contentStudioPreviewRef.current !== video) return
      drawContentStudioSideFillBackground(video, clip)
      contentStudioBackgroundFrameCallbackRef.current = { video: null, id: null }
    }

    if (typeof video.requestVideoFrameCallback === "function") {
      const id = video.requestVideoFrameCallback(drawDecodedFrame)
      contentStudioBackgroundFrameCallbackRef.current = { video, id }
    } else {
      window.requestAnimationFrame(drawDecodedFrame)
    }
  }

  function waitForContentStudioMediaReady(media, minimumReadyState = 2) {
    if (!media || media.readyState >= minimumReadyState) return Promise.resolve()

    return new Promise((resolve, reject) => {
      const timeout = window.setTimeout(() => finish(new Error("Preview media did not become ready.")), 5000)
      const cleanup = () => {
        window.clearTimeout(timeout)
        media.removeEventListener("loadeddata", handleReady)
        media.removeEventListener("canplay", handleReady)
        media.removeEventListener("error", handleError)
      }
      const finish = (error = null) => {
        cleanup()
        if (error) reject(error)
        else resolve()
      }
      const handleReady = () => {
        if (media.readyState >= minimumReadyState) finish()
      }
      const handleError = () => finish(new Error("Preview media failed to load."))

      media.addEventListener("loadeddata", handleReady)
      media.addEventListener("canplay", handleReady)
      media.addEventListener("error", handleError)
    })
  }

  async function playContentStudioTwoTracks(video, clip) {
    if (!video || !clip) return
    const backgroundVideo = clip.blurred_side_fill ? contentStudioPreviewBackgroundVideoRef.current : null
    const playbackRate = getContentStudioClipPlaybackRate(clip) * Number(contentStudioPlaybackRate || 1)
    video.playbackRate = playbackRate
    video.muted = !!clip.muted || contentStudioPreviewMuted
    if (backgroundVideo) {
      backgroundVideo.playbackRate = playbackRate
      backgroundVideo.muted = true
    }

    await Promise.all([
      waitForContentStudioMediaReady(video),
      backgroundVideo ? waitForContentStudioMediaReady(backgroundVideo) : Promise.resolve()
    ])

    if (backgroundVideo) {
      const target = Number(video.currentTime || clip.trim_start || 0)
      await Promise.all([
        waitForContentStudioSeek(video, target),
        waitForContentStudioSeek(backgroundVideo, target)
      ])
      await Promise.all([video.play(), backgroundVideo.play()])
    } else {
      await video.play()
    }
    setContentStudioTransitionFrame(null)
  }

  function captureContentStudioTransitionFrame(video, clip = null) {
    if (!video?.videoWidth || !video?.videoHeight) return null
    try {
      const canvas = document.createElement("canvas")
      canvas.width = 640
      canvas.height = 360
      const context = canvas.getContext("2d")
      if (!context) return null

      if (clip?.blurred_side_fill) {
        const crop = {
          ...(contentStudioSideFillCropByClip[clip.clip_id] || {}),
          leftPct: Number(clip.blur_crop_left_pct ?? contentStudioSideFillCropByClip[clip.clip_id]?.leftPct ?? 0),
          rightPct: Number(clip.blur_crop_right_pct ?? contentStudioSideFillCropByClip[clip.clip_id]?.rightPct ?? 0)
        }
        const leftPct = Number(crop.leftPct ?? 0)
        const rightPct = Number(crop.rightPct ?? 0)
        const sourceWidth = Number(video.videoWidth || 0)
        const sourceHeight = Number(video.videoHeight || 0)
        const cropX = Math.max(0, Math.round(sourceWidth * leftPct / 100))
        const cropRight = Math.max(0, Math.round(sourceWidth * rightPct / 100))
        const cropWidth = Math.max(2, sourceWidth - cropX - cropRight)
        const scale = Math.min(canvas.width / cropWidth, canvas.height / sourceHeight)
        const drawWidth = cropWidth * scale
        const drawHeight = sourceHeight * scale
        context.drawImage(
          video,
          cropX,
          0,
          cropWidth,
          sourceHeight,
          (canvas.width - drawWidth) / 2,
          (canvas.height - drawHeight) / 2,
          drawWidth,
          drawHeight
        )
      } else {
        context.drawImage(video, 0, 0, canvas.width, canvas.height)
      }
      return canvas.toDataURL("image/jpeg", 0.88)
    } catch (_) {
      return null
    }
  }

  function updateContentStudioDraftField(field, value) {
    setContentStudioActiveProject(currentProject => {
      if (!currentProject) return currentProject
      const draftKey = currentProject.project_type === "top10" ? "top10_draft" : "solo_draft"
      const nextProject = {
        ...currentProject,
        [draftKey]: {
          ...(currentProject[draftKey] || {}),
          [field]: value
        }
      }
      scheduleContentStudioAutosave(nextProject)
      return nextProject
    })
  }

  function updateContentStudioClip(clipId, updates, options = {}) {
    const { recordHistory = false } = options

    setContentStudioActiveProject(currentProject => {
      if (!currentProject) return currentProject

      if (recordHistory) {
        const snapshot = (currentProject.clips || []).map(clip => ({
          clip_id: clip.clip_id,
          trim_start: Number(clip.trim_start || 0),
          trim_end: Number(clip.trim_end || 0),
          order: Number(clip.order || 0)
        }))
        setContentStudioTrimHistory(history => [...history.slice(-39), snapshot])
        setContentStudioTrimFuture([])
      }

      const nextProject = {
        ...currentProject,
        status: currentProject.status === "approved" ? "edited" : currentProject.status,
        clips: (currentProject.clips || []).map(clip =>
          clip.clip_id === clipId ? { ...clip, ...updates } : clip
        )
      }

      setContentStudioPreviewConfirmed(prev => ({
        ...prev,
        [currentProject.project_id]: false
      }))
      scheduleContentStudioAutosave(nextProject)
      persistContentStudioProject(nextProject, { keepalive: true })

      return nextProject
    })
  }

  function scheduleContentStudioAutosave(projectOverride = null) {
    if (projectOverride) contentStudioLatestProjectRef.current = projectOverride
    window.clearTimeout(contentStudioAutosaveTimerRef.current)
    contentStudioAutosaveTimerRef.current = window.setTimeout(() => {
      const project = contentStudioLatestProjectRef.current || projectOverride || contentStudioActiveProject
      persistContentStudioProject(project, { keepalive: true })
    }, 180)
  }

  function restoreContentStudioTrimSnapshot(snapshot) {
    if (!snapshot || !contentStudioActiveProject) return

    const isFullSnapshot = snapshot.some(item => item && (item.file_path || item.preview_url || item.title))
    const byId = new Map(snapshot.map(item => [item.clip_id, item]))

    setContentStudioActiveProject(project => {
      if (!project) return project
      const restoredClips = isFullSnapshot
        ? snapshot.map(item => ({ ...item }))
        : (project.clips || []).map(clip => {
            const saved = byId.get(clip.clip_id)
            return saved ? {
              ...clip,
              trim_start: saved.trim_start,
              trim_end: saved.trim_end,
              order: saved.order
            } : clip
          })
      const nextProject = { ...project, clips: restoredClips, clip_count: restoredClips.length }
      scheduleContentStudioAutosave(nextProject)
      return nextProject
    })
  }

  function undoContentStudioTrim() {
    if (!contentStudioTrimHistory.length || !contentStudioActiveProject) return

    const currentSnapshot = (contentStudioActiveProject.clips || []).map(clip => ({ ...clip }))
    const previous = contentStudioTrimHistory[contentStudioTrimHistory.length - 1]

    setContentStudioTrimHistory(history => history.slice(0, -1))
    setContentStudioTrimFuture(future => [currentSnapshot, ...future].slice(0, 40))
    restoreContentStudioTrimSnapshot(previous)
  }

  function redoContentStudioTrim() {
    if (!contentStudioTrimFuture.length || !contentStudioActiveProject) return

    const currentSnapshot = (contentStudioActiveProject.clips || []).map(clip => ({ ...clip }))
    const next = contentStudioTrimFuture[0]

    setContentStudioTrimHistory(history => [...history.slice(-39), currentSnapshot])
    setContentStudioTrimFuture(future => future.slice(1))
    restoreContentStudioTrimSnapshot(next)
  }

  function resetContentStudioSelectedTrim() {
    if (!selectedClip) return
    const duration = getContentStudioClipDuration(selectedClip)

    updateContentStudioClip(
      selectedClip.clip_id,
      { trim_start: 0, trim_end: duration },
      { recordHistory: true }
    )
    seekContentStudioSelectedClipRelative(0)
    window.setTimeout(() => scheduleContentStudioAutosave(), 0)
  }

  function reorderContentStudioClips(fromClipId, toClipId) {
    if (!contentStudioActiveProject || fromClipId === toClipId) return

    setContentStudioTrimHistory(history => [...history.slice(-39), (contentStudioActiveProject.clips || []).map(item => ({ ...item }))])
    setContentStudioTrimFuture([])
    const clips = [...(contentStudioActiveProject.clips || [])]
    const fromIndex = clips.findIndex(clip => clip.clip_id === fromClipId)
    const toIndex = clips.findIndex(clip => clip.clip_id === toClipId)

    if (fromIndex < 0 || toIndex < 0) return

    const [movedClip] = clips.splice(fromIndex, 1)
    clips.splice(toIndex, 0, movedClip)

    const reordered = clips.map((clip, index) => ({
      ...clip,
      order: index + 1,
      selected_for_top10: contentStudioActiveProject.project_type === "top10" ? index < 10 : true
    }))

    const nextProject = {
      ...contentStudioActiveProject,
      clips: reordered
    }
    setContentStudioActiveProject(nextProject)
    scheduleContentStudioAutosave(nextProject)
  }

  function moveContentStudioClip(clipId, direction) {
    if (!contentStudioActiveProject) return

    const clips = [...(contentStudioActiveProject.clips || [])]
    const index = clips.findIndex(clip => clip.clip_id === clipId)
    const targetIndex = index + direction

    if (index < 0 || targetIndex < 0 || targetIndex >= clips.length) return

    const [clip] = clips.splice(index, 1)
    clips.splice(targetIndex, 0, clip)

    const reordered = clips.map((item, i) => ({
      ...item,
      order: i + 1,
      selected_for_top10: contentStudioActiveProject.project_type === "top10" ? i < 10 : true
    }))

    const nextProject = {
      ...contentStudioActiveProject,
      clips: reordered
    }
    setContentStudioActiveProject(nextProject)
    scheduleContentStudioAutosave(nextProject)
  }

  function splitContentStudioClip(clipId) {
    if (!contentStudioActiveProject) return

    const clips = [...(contentStudioActiveProject.clips || [])]
    const index = clips.findIndex(clip => clip.clip_id === clipId)
    if (index < 0) return

    const clip = clips[index]
    const trimStart = Number(clip.trim_start || 0)
    const sourceDuration = getContentStudioClipDuration(clip)
    const trimEnd = Number(clip.trim_end || 0) > trimStart ? Number(clip.trim_end) : sourceDuration
    const timelineStart = getContentStudioClipTimelineStart(clipId)
    const markerSourceTime = trimStart + Math.max(0, contentStudioPlayheadSeconds - timelineStart)
    const splitPoint = clampContentStudioNumber(markerSourceTime, trimStart + 0.12, trimEnd - 0.12)
    if (splitPoint <= trimStart || splitPoint >= trimEnd) return

    setContentStudioTrimHistory(history => [...history.slice(-39), clips.map(item => ({ ...item }))])
    setContentStudioTrimFuture([])

    const firstHalf = { ...clip, title: `${clip.title} Part 1`, trim_start: trimStart, trim_end: Number(splitPoint.toFixed(6)) }
    const secondHalf = {
      ...clip,
      clip_id: `${clip.clip_id}_split_${Date.now()}`,
      title: `${clip.title} Part 2`,
      trim_start: Number(splitPoint.toFixed(6)),
      trim_end: trimEnd,
      split_from_clip_id: clip.clip_id
    }
    clips.splice(index, 1, firstHalf, secondHalf)
    const reordered = clips.map((item, i) => ({
      ...item,
      order: i + 1,
      selected_for_top10: contentStudioActiveProject.project_type === "top10" ? i < 10 : true
    }))
    const nextProject = { ...contentStudioActiveProject, clips: reordered, clip_count: reordered.length }
    setContentStudioActiveProject(nextProject)
    scheduleContentStudioAutosave(nextProject)
    setContentStudioSelectedClipId(secondHalf.clip_id)
  }

  function removeContentStudioClipFromTimeline(clipId) {
    if (!contentStudioActiveProject) return

    setContentStudioTrimHistory(history => [...history.slice(-39), (contentStudioActiveProject.clips || []).map(item => ({ ...item }))])
    setContentStudioTrimFuture([])
    const clips = (contentStudioActiveProject.clips || [])
      .filter(clip => clip.clip_id !== clipId)
      .map((clip, index) => ({
        ...clip,
        order: index + 1,
        selected_for_top10: contentStudioActiveProject.project_type === "top10" ? index < 10 : true
      }))

    const nextProject = {
      ...contentStudioActiveProject,
      clips,
      clip_count: clips.length
    }
    setContentStudioActiveProject(nextProject)
    scheduleContentStudioAutosave(nextProject)

    if (contentStudioSelectedClipId === clipId) {
      setContentStudioSelectedClipId(clips[0]?.clip_id || null)
    }
  }

  function copyContentStudioSelectedClip() {
    const selected = getContentStudioSelectedClip()
    if (!selected) return
    contentStudioClipboardRef.current = { ...selected }
  }

  function pasteContentStudioClipboardClip() {
    const copied = contentStudioClipboardRef.current
    if (!copied || !contentStudioActiveProject) return

    const currentClips = getContentStudioSortedClips()
    const selectedIndex = Math.max(0, currentClips.findIndex(item => item.clip_id === contentStudioSelectedClipId))
    const uniqueSuffix = `${Date.now()}_${Math.random().toString(36).slice(2, 7)}`
    const baseId = String(copied.split_from_clip_id || copied.clip_id || "clip").split("_split_")[0]
    const pasted = {
      ...copied,
      clip_id: `${baseId}_split_copy_${uniqueSuffix}`,
      split_from_clip_id: baseId,
      title: `${String(copied.title || "Clip").replace(/\s+Copy(?: \d+)?$/i, "")} Copy`
    }

    const nextClips = [...currentClips]
    nextClips.splice(selectedIndex + 1, 0, pasted)
    const normalized = nextClips.map((item, index) => ({
      ...item,
      order: index + 1,
      selected_for_top10: contentStudioActiveProject.project_type === "top10" ? index < 10 : true
    }))
    const nextProject = { ...contentStudioActiveProject, clips: normalized, clip_count: normalized.length }

    setContentStudioTrimHistory(history => [...history.slice(-39), currentClips.map(item => ({ ...item }))])
    setContentStudioTrimFuture([])
    contentStudioLatestProjectRef.current = nextProject
    storeContentStudioLocalDraft(nextProject)
    setContentStudioActiveProject(nextProject)
    setContentStudioSelectedClipId(pasted.clip_id)
    scheduleContentStudioAutosave(nextProject)
    persistContentStudioProject(nextProject, { keepalive: true })
  }

  function saveContentStudioProjectEdits() {
    if (!contentStudioActiveProject) return

    const draft = getContentStudioDraft()

    fetch(`${API}/content-studio/project/${contentStudioActiveProject.project_id}/edit`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        project_name: contentStudioActiveProject.project_name,
        clips: (contentStudioActiveProject.clips || []).map((clip, index) => ({
          clip_id: clip.clip_id,
          order: index + 1,
          title: clip.title,
          trim_start: Number(clip.trim_start || 0),
          trim_end: Number(clip.trim_end || 0),
          duration_seconds: Number(clip.duration_seconds || 0),
          selected_for_top10: !!clip.selected_for_top10,
          frame_x: Number(clip.frame_x || 0),
          frame_y: Number(clip.frame_y || 0),
          frame_scale: Number(clip.frame_scale || 1),
          source_fps: Number(clip.source_fps || 0),
          muted: !!clip.muted,
          playback_rate: getContentStudioClipPlaybackRate(clip),
          blurred_side_fill: !!clip.blurred_side_fill,
          blur_crop_left_pct: Number(clip.blur_crop_left_pct ?? 0),
          blur_crop_right_pct: Number(clip.blur_crop_right_pct ?? 0),
          blur_crop_offset_pct: Number(clip.blur_crop_offset_pct ?? 0)
        })),
        top10_draft: contentStudioActiveProject.project_type === "top10" ? draft : null,
        solo_draft: contentStudioActiveProject.project_type === "solo" ? draft : null
      })
    })
      .then(async r => {
        const data = await r.json()

        if (!r.ok || data.found === false) {
          showCourtVisionDialog("Project save failed: " + JSON.stringify(data))
          return
        }

        setContentStudioActiveProject(data.project)
        setContentStudioSelectedClipId(data.project?.clips?.[0]?.clip_id || contentStudioSelectedClipId)
        loadContentStudioData()
        showCourtVisionDialog("Project edits saved.", { title: "Project Saved", type: "success" })
      })
      .catch(err => showCourtVisionDialog("Project save failed: " + err.message))
  }

  function approveContentStudioProject(openActionCenter = false) {
    if (!contentStudioActiveProject) return

    // The Finish Project menu is a local editor action and must open immediately.
    // Backend approval is still saved in parallel, but a slow or failed request
    // must never make the Confirm Edit button appear unresponsive.
    if (openActionCenter) setContentStudioActionModalOpen(true)

    fetch(`${API}/content-studio/project/${contentStudioActiveProject.project_id}/approve`, {
      method: "PUT"
    })
      .then(async r => {
        const data = await r.json()

        if (!r.ok || data.found === false) {
          showCourtVisionDialog("Project approval failed: " + JSON.stringify(data))
          return
        }

        setContentStudioActiveProject(data.project)
        loadContentStudioData()

        if (!openActionCenter) {
          showCourtVisionDialog("Project approved. Use Upload to YouTube only when you are ready to publish.", { title: "Edit Approved", type: "success" })
        }
      })
      .catch(err => showCourtVisionDialog("Project approval failed: " + err.message))
  }


  function clampContentStudioNumber(value, min, max) {
    const number = Number(value || 0)

    if (Number.isNaN(number)) return min
    if (number < min) return min
    if (number > max) return max

    return Number(number.toFixed(2))
  }

  function normalizeContentStudioTime(value) {
    const number = Number(value || 0)
    if (!Number.isFinite(number)) return 0
    return Number(Math.max(0, number).toFixed(6))
  }

  function snapContentStudioTimeToSourceFrame(value, clip) {
    const fps = getContentStudioSourceFps(clip)
    if (!Number.isFinite(fps) || fps <= 0) return normalizeContentStudioTime(value)
    return normalizeContentStudioTime(Math.round(Number(value || 0) * fps) / fps)
  }

  function getContentStudioClipDuration(clip) {
    const explicitDuration = Number(clip?.duration_seconds || clip?.duration || 0)

    if (explicitDuration > 0) return explicitDuration

    const trimEnd = Number(clip?.trim_end || 0)

    if (trimEnd > 0) return trimEnd

    return 120
  }

  function getContentStudioSortedClips(project = contentStudioActiveProject) {
    return [...(project?.clips || [])].sort((a, b) => Number(a.order || 0) - Number(b.order || 0))
  }

  function getContentStudioClipPlaybackRate(clip) {
    return clampContentStudioNumber(clip?.playback_rate || 1, 0.25, 4)
  }

  function getContentStudioEffectiveClipDuration(clip) {
    const fullDuration = getContentStudioClipDuration(clip)
    const start = Number(clip?.trim_start || 0)
    const rawEnd = Number(clip?.trim_end || 0)
    const end = rawEnd > start ? rawEnd : fullDuration
    const playbackRate = getContentStudioClipPlaybackRate(clip)

    return Math.max(0.25, (end - start) / playbackRate)
  }

  function getContentStudioTimelineTotalSeconds(project = contentStudioActiveProject) {
    const clips = getContentStudioSortedClips(project)
    const clipSeconds = clips.reduce((total, clip) => total + getContentStudioEffectiveClipDuration(clip), 0)

    return Number(Math.max(0.25, clipSeconds).toFixed(2))
  }

  function getContentStudioFinalDurationSeconds(project = contentStudioActiveProject) {
    return Number((getContentStudioTimelineTotalSeconds(project) + 15).toFixed(2))
  }

  function getContentStudioClipTimelineStart(clipId, project = contentStudioActiveProject) {
    const clips = getContentStudioSortedClips(project)
    let cursor = 0

    for (const clip of clips) {
      if (clip.clip_id === clipId) return cursor
      cursor += getContentStudioEffectiveClipDuration(clip)
    }

    return 0
  }

  function getContentStudioSourceFps(clip = null) {
    const raw = Number(clip?.source_fps || contentStudioActiveProject?.clips?.[0]?.source_fps || 30)
    if (!Number.isFinite(raw) || raw <= 0) return 30
    // Keep the exact probed rate (for example 23.976, 29.97, or 59.94).
    // Quantizing it to 30/60 made frame stepping, timeline snapping, and trim
    // boundaries disagree with the frames the browser was actually decoding.
    return Number(raw.toFixed(6))
  }

  function formatContentStudioFps(value) {
    const raw = Number(value || 0)
    if (!Number.isFinite(raw) || raw <= 0) return "30"
    return raw.toFixed(3).replace(/\.?0+$/, "")
  }

  function formatRenderEta(seconds) {
    const value = Math.max(0, Math.round(Number(seconds || 0)))
    if (value <= 0) return "Less than 1 second"
    if (value < 60) return `${value} second${value === 1 ? "" : "s"}`
    const minutes = Math.floor(value / 60)
    const remainder = value % 60
    return `${minutes} minute${minutes === 1 ? "" : "s"}${remainder ? ` ${remainder} seconds` : ""}`
  }

  function estimateContentStudioRenderSeconds(project = contentStudioActiveProject, outputFps = contentStudioOutputFps, interpolationMode = contentStudioInterpolationMode) {
    const clips = project?.clips || []
    const sourceFps = getContentStudioSourceFps(clips[0] || null)
    const targetFps = Number(outputFps || 0) > 0 ? Number(outputFps) : sourceFps
    const interpolation = targetFps > sourceFps && !["none", "off", "original"].includes(String(interpolationMode || "auto").toLowerCase())
    const selectedClips = project?.project_type === "top10"
      ? clips.filter(clip => clip.selected_for_top10 !== false).slice(0, 10)
      : clips
    const mainSeconds = selectedClips.reduce((total, clip) => total + Math.max(0.25, getContentStudioEffectiveClipDuration(clip)), 0)
    const fpsRatio = Math.max(1, targetFps / Math.max(1, sourceFps))
    let secondsPerSourceSecond
    if (interpolation) {
      secondsPerSourceSecond = 2.8 + (fpsRatio - 1) * 2.2 + (targetFps >= 120 ? 0.8 : 0)
    } else {
      secondsPerSourceSecond = project?.project_type === "top10" ? 0.58 : 0.42
    }
    return Math.max(8, Math.round(mainSeconds * secondsPerSourceSecond + 15 * 0.35 + (project?.project_type === "top10" ? 18 : 8)))
  }

  function seekContentStudioTimeline(seconds) {
    if (!contentStudioActiveProject) return

    setContentStudioPreviewOutroActive(false)

    const clips = getContentStudioSortedClips()
    const totalSeconds = getContentStudioTimelineTotalSeconds()
    const numericSeconds = Number(seconds || 0)
    const nextTime = Math.max(0, Math.min(totalSeconds, Number.isFinite(numericSeconds) ? numericSeconds : 0))
    let cursor = 0

    // Update both React state and the DOM position immediately so the marker
    // responds on the exact click/drag frame without waiting for a render pass.
    updateContentStudioPlayheadVisual(nextTime)

    for (let clipIndex = 0; clipIndex < clips.length; clipIndex += 1) {
      const clip = clips[clipIndex]
      const clipLength = getContentStudioEffectiveClipDuration(clip)
      const clipStart = Number(clip.trim_start || 0)
      const clipEnd = cursor + clipLength
      const isLastClip = clipIndex === clips.length - 1

      // A shared boundary belongs to the following clip. Selecting the outgoing
      // clip at exactly clipEnd sought to its exclusive trim_end and exposed a
      // frame that is not present in the FFmpeg render.
      if (nextTime >= cursor - 0.0001 && (nextTime < clipEnd - 0.0001 || isLastClip)) {
        const playbackRate = getContentStudioClipPlaybackRate(clip)
        const sourceFrame = 1 / Math.max(1, getContentStudioSourceFps(clip))
        const rawSourceEnd = Number(clip.trim_end || 0) > clipStart ? Number(clip.trim_end) : getContentStudioClipDuration(clip)
        const lastIncludedSourceTime = Math.max(clipStart, rawSourceEnd - sourceFrame)
        const requestedSourceTime = clipStart + Math.max(0, (nextTime - cursor) * playbackRate)
        const sourceTime = Math.min(lastIncludedSourceTime, requestedSourceTime)
        contentStudioPendingSeekRef.current = {
          clipId: clip.clip_id,
          sourceTime,
          timelineTime: nextTime,
          resumePlayback: false
        }

        const activeClip = getContentStudioSelectedClip()
        const video = contentStudioPreviewRef.current

        if (activeClip?.clip_id !== clip.clip_id) {
          setContentStudioSelectedClipId(clip.clip_id)
        } else if (video) {
          if (clip.blurred_side_fill) setContentStudioTwoTrackTime(sourceTime)
          else {
            try { video.currentTime = sourceTime } catch (_) {}
          }
        }
        return
      }

      cursor = clipEnd
    }
  }

  function getContentStudioTimelineSecondsFromPointer(event, lane) {
    if (!lane) return 0

    const rect = lane.getBoundingClientRect()
    const pointerX = Number(event.clientX || 0) - rect.left
    const pixelsPerSecond = Math.max(4, Math.min(32, Number(contentStudioTimelineZoom || 12)))
    const totalSeconds = getContentStudioTimelineTotalSeconds()
    const rawSeconds = Math.max(0, Math.min(totalSeconds, pointerX / pixelsPerSecond))
    const sourceFps = Math.max(1, getContentStudioSourceFps(getContentStudioSelectedClip()))

    // Snap to the actual source frame so clicks and releases remain exact at
    // every zoom level instead of drifting because of rounded percentages.
    return Math.max(0, Math.min(totalSeconds, Math.round(rawSeconds * sourceFps) / sourceFps))
  }

  function seekContentStudioTimelineFromPointer(event, lane) {
    if (!lane) return
    seekContentStudioTimeline(getContentStudioTimelineSecondsFromPointer(event, lane))
  }

  function handleContentStudioTimelinePointerDown(event, explicitLane = null) {
    if (event.button !== 0) return
    if (event.target.closest(".nle-trim-handle, .nle-clip-actions, .nle-static-asset.outro")) return

    const lane = explicitLane || event.currentTarget
    if (!lane) return

    event.preventDefault()
    event.stopPropagation()

    try {
      lane.setPointerCapture?.(event.pointerId)
    } catch (_) {}

    contentStudioTimelineDragRef.current = {
      pointerId: event.pointerId,
      lane,
      moved: false
    }

    document.body.classList.add("editor-scrubbing")
    pauseContentStudioPreview()
    seekContentStudioTimelineFromPointer(event, lane)
  }

  function handleContentStudioTimelinePointerMove(event) {
    const drag = contentStudioTimelineDragRef.current
    if (!drag || drag.pointerId !== event.pointerId) return

    event.preventDefault()
    drag.moved = true
    seekContentStudioTimelineFromPointer(event, drag.lane)
  }

  function handleContentStudioTimelinePointerUp(event) {
    const drag = contentStudioTimelineDragRef.current
    if (!drag || drag.pointerId !== event.pointerId) return

    event.preventDefault()

    // The release coordinates are authoritative. This prevents the marker from
    // jumping backward when pointer-move events are throttled at high zoom.
    seekContentStudioTimelineFromPointer(event, drag.lane)

    try {
      drag.lane?.releasePointerCapture?.(event.pointerId)
    } catch (_) {}

    contentStudioTimelineDragRef.current = { suppressClick: true }
    window.setTimeout(() => {
      if (contentStudioTimelineDragRef.current?.suppressClick) {
        contentStudioTimelineDragRef.current = null
      }
    }, 0)

    document.body.classList.remove("editor-scrubbing")
  }

  function handleContentStudioTimelineClick(event, explicitLane = null) {
    if (contentStudioTimelineDragRef.current?.suppressClick) return
    if (event.target.closest(".nle-trim-handle, .nle-clip-actions, .nle-static-asset.outro")) return

    event.preventDefault()
    event.stopPropagation()
    pauseContentStudioPreview()
    seekContentStudioTimelineFromPointer(event, explicitLane || event.currentTarget)
  }

  function captureContentStudioTransitionFrame(video) {
    if (!video || Number(video.videoWidth || 0) <= 0 || Number(video.videoHeight || 0) <= 0) return null

    try {
      const canvas = document.createElement("canvas")
      canvas.width = Number(video.videoWidth)
      canvas.height = Number(video.videoHeight)
      const context = canvas.getContext("2d", { alpha: false })
      if (!context) return null
      context.drawImage(video, 0, 0, canvas.width, canvas.height)
      return canvas.toDataURL("image/jpeg", 0.94)
    } catch (_) {
      return null
    }
  }

  function revealContentStudioTransitionBridge(video) {
    if (!video) return
    video.classList.add("is-transition-bridge")
    video.style.visibility = "visible"
    video.style.opacity = "1"
  }

  function transitionContentStudioToNextClip(video, clip) {
    if (!video || !clip) return false

    const sortedClips = getContentStudioSortedClips()
    const currentIndex = sortedClips.findIndex(item => item.clip_id === clip.clip_id)
    const nextClip = currentIndex >= 0 ? sortedClips[currentIndex + 1] : null
    const existingTransition = contentStudioTransitionLockRef.current
    if (existingTransition?.fromClipId === clip.clip_id) return true

    contentStudioTransitionLockRef.current = {
      fromClipId: clip.clip_id,
      toClipId: nextClip?.clip_id || null
    }
    const clipTimelineStart = getContentStudioClipTimelineStart(clip.clip_id)
    const clipEndTime = Number((clipTimelineStart + getContentStudioEffectiveClipDuration(clip)).toFixed(3))

    // Freeze on the last included frame, never on trim_end itself. trim_end is
    // an exclusive boundary in the render pipeline, so displaying it in the
    // HTML preview exposed one or more frames that the final render omits.
    stopContentStudioPlayheadSync()
    updateContentStudioPlayheadVisual(clipEndTime, clip)
    setContentStudioPlayheadSeconds(clipEndTime)

    if (!nextClip) {
      contentStudioPlaybackIntentRef.current = false
      contentStudioTransitionLockRef.current = null
      setContentStudioPreviewPlaying(false)
      setContentStudioPreviewOutroActive(true)
      return true
    }

    const preloadedNext = contentStudioNextClipPreloadRef.current
    const preloadedNextBackground = nextClip.blurred_side_fill
      ? contentStudioNextClipBackgroundPreloadRef.current
      : null
    const nextTimelineStart = getContentStudioClipTimelineStart(nextClip.clip_id)
    const nextSourceTime = Number(nextClip.trim_start || 0)
    const shouldContinuePlaying = contentStudioPlaybackIntentRef.current === true

    // Stop and hide the outgoing decoder immediately at the exclusive trim
    // boundary. This prevents queued browser frames beyond trim_end from ever
    // painting while the next React video element is mounted.
    pauseContentStudioTwoTracks()
    try { video.style.visibility = "hidden" } catch (_) {}

    const finishClipSwap = () => {
      contentStudioContinuePlaybackRef.current = shouldContinuePlaying ? nextClip.clip_id : null
      contentStudioPendingSeekRef.current = {
        clipId: nextClip.clip_id,
        sourceTime: nextSourceTime,
        timelineTime: nextTimelineStart,
        resumePlayback: shouldContinuePlaying
      }
      setContentStudioPreviewOutroActive(false)
      setContentStudioSelectedClipId(nextClip.clip_id)
      setContentStudioPlayheadSeconds(Number(nextTimelineStart.toFixed(3)))
    }

    if (preloadedNext && preloadedNext.readyState >= 2) {
      const showDecodedNextFrame = async () => {
        // Both next-clip decoders are warmed and held on the same first legal
        // frame before ownership changes. This prevents the foreground from
        // appearing first and freezing while the blurred layer catches up.
        preloadedNext.pause()
        preloadedNext.playbackRate = getContentStudioClipPlaybackRate(nextClip) * Number(contentStudioPlaybackRate || 1)
        preloadedNext.muted = true
        if (preloadedNextBackground) {
          preloadedNextBackground.pause()
          preloadedNextBackground.playbackRate = preloadedNext.playbackRate
          preloadedNextBackground.muted = true
          await waitForContentStudioMediaReady(preloadedNextBackground)
          await waitForContentStudioSeek(preloadedNextBackground, nextSourceTime)
        }
        const capturedFrame = captureContentStudioTransitionFrame(preloadedNext)

        // Decode the transition cover before swapping React video elements.
        // Setting image state and swapping on the next animation frame could
        // still expose one black browser paint while the data URL decoded.
        if (capturedFrame) {
          try {
            const image = new Image()
            image.src = capturedFrame
            if (typeof image.decode === "function") await image.decode()
          } catch (_) {}
          setContentStudioTransitionFrame(capturedFrame)
          await new Promise(resolve => window.requestAnimationFrame(() => window.requestAnimationFrame(resolve)))
        }
        finishClipSwap()
      }

      const tolerance = Math.max(0.004, 0.25 / Math.max(1, getContentStudioSourceFps(nextClip)))
      if (Math.abs(Number(preloadedNext.currentTime || 0) - nextSourceTime) <= tolerance && !preloadedNext.seeking) {
        showDecodedNextFrame()
      } else {
        const onBridgeSeeked = () => showDecodedNextFrame()
        preloadedNext.addEventListener("seeked", onBridgeSeeked, { once: true })
        try { preloadedNext.currentTime = nextSourceTime } catch (_) { showDecodedNextFrame() }
      }
    } else {
      finishClipSwap()
    }
    return true
  }

  function handleContentStudioPreviewTimeUpdate(event, clip) {
    if (!clip) return
    if (contentStudioTimelineDragRef.current?.pointerId !== undefined) return

    const video = event.currentTarget
    const pendingSeek = contentStudioPendingSeekRef.current
    if (pendingSeek?.clipId === clip.clip_id) {
      const fps = getContentStudioSourceFps(clip)
      const tolerance = Math.max(0.025, 1 / Math.max(1, fps))
      const reachedTarget = Math.abs(Number(video.currentTime || 0) - Number(pendingSeek.sourceTime || 0)) <= tolerance

      // The seeked handler owns transition completion. Do not clear a pending
      // resume request from timeupdate: doing so erased the command to keep
      // playing before Clip 2's seeked event fired, leaving every next clip
      // paused on its first frame.
      if (pendingSeek.resumePlayback === true) return
      if (!reachedTarget) return
    }
    const clipTimelineStart = getContentStudioClipTimelineStart(clip.clip_id)
    const clipTrimStart = Number(clip.trim_start || 0)
    const clipDuration = getContentStudioClipDuration(clip)
    const rawTrimEnd = Number(clip.trim_end || 0)
    const clipTrimEnd = rawTrimEnd > clipTrimStart ? rawTrimEnd : clipDuration
    const currentTime = Number(video.currentTime || 0)

    // Automatic clip ownership changes are handled only by the decoded-frame
    // synchronization loop. timeupdate is intentionally not a second boundary
    // trigger because browser timeupdate events are coarse and may arrive after
    // an excluded frame has already painted.
    const playbackRate = getContentStudioClipPlaybackRate(clip)
    const relativeTime = clampContentStudioNumber((currentTime - clipTrimStart) / playbackRate, 0, getContentStudioEffectiveClipDuration(clip))

    setContentStudioPlayheadSeconds(Number((clipTimelineStart + relativeTime).toFixed(2)))
  }

  function handleContentStudioPreviewSeeked(event, clip) {
    if (!clip) return
    const video = event.currentTarget

    const backgroundVideo = clip.blurred_side_fill ? contentStudioPreviewBackgroundVideoRef.current : null
    if (backgroundVideo) {
      const targetTime = Number(video.currentTime || 0)
      if (Math.abs(Number(backgroundVideo.currentTime || 0) - targetTime) > 0.008) {
        try { backgroundVideo.currentTime = targetTime } catch (_) {}
      }
    }

    const pendingSeek = contentStudioPendingSeekRef.current
    if (pendingSeek?.clipId !== clip.clip_id) return

    const sourceTime = Number(video.currentTime || pendingSeek.sourceTime || 0)
    const timelineStart = getContentStudioClipTimelineStart(clip.clip_id)
    const trimStart = Number(clip.trim_start || 0)
    const relative = clampContentStudioNumber(
      (sourceTime - trimStart) / getContentStudioClipPlaybackRate(clip),
      0,
      getContentStudioEffectiveClipDuration(clip)
    )
    setContentStudioPlayheadSeconds(Number((timelineStart + relative).toFixed(3)))

    const releaseTransitionCover = () => {
      window.requestAnimationFrame(() => {
        try { video.style.visibility = "visible" } catch (_) {}
        setContentStudioTransitionFrame(null)
      })
    }

    const shouldResume = pendingSeek.resumePlayback === true && contentStudioContinuePlaybackRef.current === clip.clip_id
    contentStudioPendingSeekRef.current = null
    if (contentStudioTransitionLockRef.current?.toClipId === clip.clip_id) {
      contentStudioTransitionLockRef.current = null
    }

    if (!shouldResume) {
      contentStudioContinuePlaybackRef.current = null
      pauseContentStudioTwoTracks()
      setContentStudioPreviewPlaying(false)
      return
    }

    // Resume only after the seek to Clip 2's trim_start has actually completed.
    // Starting from loadedmetadata raced the seek and could play stale frames.
    contentStudioContinuePlaybackRef.current = null
    video.playbackRate = getContentStudioClipPlaybackRate(clip) * Number(contentStudioPlaybackRate || 1)
    video.muted = !!clip.muted || contentStudioPreviewMuted
    playContentStudioTwoTracks(video, clip).then(() => {
      // The cover remains above both real videos until both decoders have
      // started from the same source moment, then disappears in one paint.
      releaseTransitionCover()
      setContentStudioPreviewPlaying(true)
      startContentStudioPlayheadSync(video, clip)
    }).catch(() => setContentStudioPreviewPlaying(false))
  }

  function getContentStudioTimelineClipWidth(clip) {
    const effectiveSeconds = getContentStudioEffectiveClipDuration(clip)
    const pixelsPerSecond = clampContentStudioNumber(contentStudioTimelineZoom, 4, 32)

    return Math.max(20, Math.min(6400, effectiveSeconds * pixelsPerSecond))
  }

  function getContentStudioSelectedClip(project = contentStudioActiveProject) {
    const clips = getContentStudioSortedClips(project)
    return clips.find(clip => clip.clip_id === contentStudioSelectedClipId) || clips[0] || null
  }

  function getContentStudioPreviewRelativeTime(clip = null) {
    const activeClip = clip || getContentStudioSelectedClip()
    if (!activeClip) return 0

    const timelineStart = getContentStudioClipTimelineStart(activeClip.clip_id)
    return clampContentStudioNumber(
      contentStudioPlayheadSeconds - timelineStart,
      0,
      getContentStudioEffectiveClipDuration(activeClip)
    )
  }

  function seekContentStudioSelectedClipRelative(relativeSeconds) {
    const activeClip = getContentStudioSelectedClip()
    const video = contentStudioPreviewRef.current
    if (!activeClip || !video) return

    setContentStudioPreviewOutroActive(false)

    const start = Number(activeClip.trim_start || 0)
    const duration = getContentStudioEffectiveClipDuration(activeClip)
    const relative = clampContentStudioNumber(relativeSeconds, 0, duration)
    const sourceTime = start + (relative * getContentStudioClipPlaybackRate(activeClip))
    const timelineStart = getContentStudioClipTimelineStart(activeClip.clip_id)

    if (activeClip.blurred_side_fill) setContentStudioTwoTrackTime(sourceTime)
    else {
      try { video.currentTime = sourceTime } catch (_) {}
    }

    setContentStudioPlayheadSeconds(Number((timelineStart + relative).toFixed(2)))
  }

  function getContentStudioFrameDuration(clip = null) {
    return 1 / Math.max(1, getContentStudioSourceFps(clip || getContentStudioSelectedClip()))
  }

  function stepContentStudioFrame(direction) {
    const activeClip = getContentStudioSelectedClip()
    if (!activeClip) return

    pauseContentStudioPreview()

    const stepDirection = Number(direction || 0)
    const frameDuration = getContentStudioFrameDuration(activeClip)
    const currentRelative = getContentStudioPreviewRelativeTime(activeClip)
    const clipDuration = getContentStudioEffectiveClipDuration(activeClip)
    const sortedClips = getContentStudioSortedClips()
    const currentIndex = sortedClips.findIndex(item => item.clip_id === activeClip.clip_id)

    // trim_end is exclusive. When Next Frame advances beyond the final included
    // frame, move directly to the first frame at the next clip's trim_start
    // instead of clamping at the end of the current clip.
    if (stepDirection > 0 && currentRelative + frameDuration >= clipDuration - 0.000001) {
      const nextClip = currentIndex >= 0 ? sortedClips[currentIndex + 1] : null
      if (!nextClip) {
        seekContentStudioSelectedClipRelative(Math.max(0, clipDuration - frameDuration))
        return
      }

      const nextTimelineStart = getContentStudioClipTimelineStart(nextClip.clip_id)
      const nextSourceTime = Number(nextClip.trim_start || 0)

      // Frame stepping must remain paused while crossing clip boundaries. Clear
      // any playback-continuation request left by normal real-time playback.
      contentStudioContinuePlaybackRef.current = null
      setContentStudioPreviewPlaying(false)
      contentStudioPendingSeekRef.current = {
        clipId: nextClip.clip_id,
        sourceTime: nextSourceTime,
        timelineTime: nextTimelineStart,
        resumePlayback: false
      }
      setContentStudioPreviewOutroActive(false)
      setContentStudioSelectedClipId(nextClip.clip_id)
      updateContentStudioPlayheadVisual(nextTimelineStart, nextClip)
      setContentStudioPlayheadSeconds(Number(nextTimelineStart.toFixed(3)))
      return
    }

    if (stepDirection < 0 && currentRelative - frameDuration < -0.000001) {
      const previousClip = currentIndex > 0 ? sortedClips[currentIndex - 1] : null
      if (!previousClip) {
        seekContentStudioSelectedClipRelative(0)
        return
      }

      const previousFrameDuration = getContentStudioFrameDuration(previousClip)
      const previousDuration = getContentStudioEffectiveClipDuration(previousClip)
      const previousRelative = Math.max(0, previousDuration - previousFrameDuration)
      const previousTimelineStart = getContentStudioClipTimelineStart(previousClip.clip_id)
      const previousSourceTime = Number(previousClip.trim_start || 0) + (previousRelative * getContentStudioClipPlaybackRate(previousClip))

      contentStudioContinuePlaybackRef.current = null
      setContentStudioPreviewPlaying(false)
      contentStudioPendingSeekRef.current = {
        clipId: previousClip.clip_id,
        sourceTime: previousSourceTime,
        timelineTime: previousTimelineStart + previousRelative,
        resumePlayback: false
      }
      setContentStudioPreviewOutroActive(false)
      setContentStudioSelectedClipId(previousClip.clip_id)
      updateContentStudioPlayheadVisual(previousTimelineStart + previousRelative, previousClip)
      setContentStudioPlayheadSeconds(Number((previousTimelineStart + previousRelative).toFixed(3)))
      return
    }

    seekContentStudioSelectedClipRelative(currentRelative + (stepDirection * frameDuration))
  }

  function stopContentStudioFrameHold() {
    if (contentStudioFrameStepDelayRef.current) {
      window.clearTimeout(contentStudioFrameStepDelayRef.current)
      contentStudioFrameStepDelayRef.current = null
    }
    if (contentStudioFrameStepIntervalRef.current) {
      window.clearInterval(contentStudioFrameStepIntervalRef.current)
      contentStudioFrameStepIntervalRef.current = null
    }
  }

  function startContentStudioFrameHold(event, direction) {
    event.preventDefault()
    stopContentStudioFrameHold()
    stepContentStudioFrame(direction)
    contentStudioFrameStepDelayRef.current = window.setTimeout(() => {
      contentStudioFrameStepIntervalRef.current = window.setInterval(() => {
        stepContentStudioFrame(direction)
      }, 70)
    }, 320)
  }

  function updateContentStudioPlayheadVisual(timelineSeconds, clip = null) {
    const totalSeconds = getContentStudioTimelineTotalSeconds()
    const safeSeconds = Math.max(0, Math.min(totalSeconds, Number(timelineSeconds || 0)))

    // Move the visible marker directly on every decoded video frame, but avoid
    // forcing the entire editor React tree to re-render at 30/60 FPS. State is
    // refreshed at a smooth UI cadence and is still forced at clip boundaries,
    // seeks, pauses, and trim operations by their existing handlers.
    const element = contentStudioPlayheadElementRef.current
    if (element) {
      const pixelsPerSecond = clampContentStudioNumber(contentStudioTimelineZoom, 4, 32)
      element.style.left = `${safeSeconds * pixelsPerSecond}px`
    }

    const now = typeof performance !== "undefined" ? performance.now() : Date.now()
    if (now - Number(contentStudioLastPlayheadStateUpdateRef.current || 0) >= 80) {
      contentStudioLastPlayheadStateUpdateRef.current = now
      setContentStudioPlayheadSeconds(Number(safeSeconds.toFixed(3)))
    }
  }

  function stopContentStudioPlayheadSync() {
    const current = contentStudioPlaybackFrameRef.current || {}
    const video = current.video

    if (current.kind === "video-frame" && video?.cancelVideoFrameCallback && current.id !== null) {
      try { video.cancelVideoFrameCallback(current.id) } catch (_) {}
    } else if (current.kind === "animation-frame" && current.id !== null) {
      window.cancelAnimationFrame(current.id)
    }

    contentStudioPlaybackFrameRef.current = { kind: null, id: null, video: null }
  }

  function startContentStudioPlayheadSync(video, clip) {
    if (!video || !clip) return
    stopContentStudioPlayheadSync()

    const trimStart = Number(clip.trim_start || 0)
    const clipLength = getContentStudioEffectiveClipDuration(clip)
    const timelineStart = getContentStudioClipTimelineStart(clip.clip_id)

    const syncFrame = (_now, metadata = null) => {
      if (contentStudioPreviewRef.current !== video || video.paused || video.ended) {
        stopContentStudioPlayheadSync()
        return
      }

      const mediaTime = Number(metadata?.mediaTime ?? video.currentTime ?? trimStart)
      const relative = Math.max(0, Math.min(clipLength, (mediaTime - trimStart) / getContentStudioClipPlaybackRate(clip)))
      if (clip.blurred_side_fill) {
        const backgroundVideo = contentStudioPreviewBackgroundVideoRef.current
        if (backgroundVideo) {
          const drift = Number(backgroundVideo.currentTime || 0) - mediaTime
          const baseRate = video.playbackRate
          const hardSyncThreshold = Math.max(0.12, 3 / Math.max(1, getContentStudioSourceFps(clip)))

          // Avoid hard-seeking the blurred video for normal tiny decoder drift;
          // repeated currentTime assignments are what made it visibly jump.
          // Gently correct with playback rate and reserve a seek for large drift.
          if (Math.abs(drift) > hardSyncThreshold && !backgroundVideo.seeking) {
            try { backgroundVideo.currentTime = mediaTime } catch (_) {}
            backgroundVideo.playbackRate = baseRate
          } else if (drift > 0.012) {
            backgroundVideo.playbackRate = Math.max(0.25, baseRate * 0.985)
          } else if (drift < -0.012) {
            backgroundVideo.playbackRate = Math.min(16, baseRate * 1.015)
          } else {
            backgroundVideo.playbackRate = baseRate
          }
          if (video.paused && !backgroundVideo.paused) backgroundVideo.pause()
          if (!video.paused && backgroundVideo.paused && backgroundVideo.readyState >= 2) {
            backgroundVideo.play().catch(() => {})
          }
        }
      }
      updateContentStudioPlayheadVisual(timelineStart + relative, clip)

      const rawTrimEnd = Number(clip.trim_end || 0)
      const trimEnd = rawTrimEnd > trimStart ? rawTrimEnd : getContentStudioClipDuration(clip)
      const sourceFrame = 1 / Math.max(1, getContentStudioSourceFps(clip))
      // Switch as soon as the final included source frame has been presented.
      // Do not seek to trimEnd: that boundary belongs to the next/excluded frame.
      // Browser frame callbacks run after a frame is submitted for display.
      // Hand ownership over slightly before the exclusive boundary so queued
      // decoder frames at/after trim_end cannot flash in the monitor.
      const transitionBoundary = Math.max(trimStart, trimEnd - (sourceFrame * 1.5))
      if (trimEnd > trimStart && mediaTime >= transitionBoundary) {
        transitionContentStudioToNextClip(video, clip)
        return
      }

      if (typeof video.requestVideoFrameCallback === "function") {
        const id = video.requestVideoFrameCallback(syncFrame)
        contentStudioPlaybackFrameRef.current = { kind: "video-frame", id, video }
      } else {
        const id = window.requestAnimationFrame(syncFrame)
        contentStudioPlaybackFrameRef.current = { kind: "animation-frame", id, video }
      }
    }

    if (typeof video.requestVideoFrameCallback === "function") {
      const id = video.requestVideoFrameCallback(syncFrame)
      contentStudioPlaybackFrameRef.current = { kind: "video-frame", id, video }
    } else {
      const id = window.requestAnimationFrame(syncFrame)
      contentStudioPlaybackFrameRef.current = { kind: "animation-frame", id, video }
    }
  }

  async function playContentStudioPreview() {
    contentStudioPlaybackIntentRef.current = true
    const activeClip = getContentStudioSelectedClip()
    const video = contentStudioPreviewRef.current
    if (!video || !activeClip) return

    setContentStudioPreviewOutroActive(false)

    const start = Number(activeClip.trim_start || 0)
    const end = Number(activeClip.trim_end || 0) > start
      ? Number(activeClip.trim_end)
      : getContentStudioClipDuration(activeClip)

    if (Number(video.currentTime || 0) < start || Number(video.currentTime || 0) >= end) {
      try {
        video.currentTime = start
      } catch (_) {}
    }

    try {
      await playContentStudioTwoTracks(video, activeClip)
      setContentStudioPreviewPlaying(true)
      startContentStudioPlayheadSync(video, activeClip)
    } catch (error) {
      contentStudioPlaybackIntentRef.current = false
      console.error("Preview playback failed:", error)
      setContentStudioPreviewPlaying(false)
    }
  }

  function pauseContentStudioPreview() {
    contentStudioPlaybackIntentRef.current = false
    const video = contentStudioPreviewRef.current
    if (!video) return
    pauseContentStudioTwoTracks()
    stopContentStudioPlayheadSync()
    setContentStudioPreviewPlaying(false)
  }

  function stopContentStudioPreview() {
    contentStudioPlaybackIntentRef.current = false
    const activeClip = getContentStudioSelectedClip()
    const video = contentStudioPreviewRef.current
    if (!video || !activeClip) return

    pauseContentStudioTwoTracks()
    stopContentStudioPlayheadSync()
    const start = Number(activeClip.trim_start || 0)
    if (activeClip.blurred_side_fill) setContentStudioTwoTrackTime(start)
    else {
      try { video.currentTime = start } catch (_) {}
    }

    setContentStudioPlayheadSeconds(
      Number(getContentStudioClipTimelineStart(activeClip.clip_id).toFixed(2))
    )
    setContentStudioPreviewPlaying(false)
    setContentStudioPreviewOutroActive(false)
  }

  function startContentStudioTrimDrag(event, clip, side) {
    if (!clip || !contentStudioActiveProject) return

    event.preventDefault()
    event.stopPropagation()
    event.currentTarget?.setPointerCapture?.(event.pointerId)

    const timeStretchMode = !!event.ctrlKey && side === "right"
    const startX = event.clientX
    const duration = getContentStudioClipDuration(clip)
    const originalStart = Number(clip.trim_start || 0)
    const originalEnd = Number(clip.trim_end || 0) > originalStart
      ? Number(clip.trim_end)
      : duration
    const pixelsPerSecond = clampContentStudioNumber(contentStudioTimelineZoom, 4, 32)
    const minimumLength = 0.25
    let latestStart = originalStart
    let latestEnd = originalEnd
    const originalPlaybackRate = getContentStudioClipPlaybackRate(clip)
    const originalTimelineDuration = Math.max(0.25, (originalEnd - originalStart) / originalPlaybackRate)
    let latestPlaybackRate = originalPlaybackRate

    const historySnapshot = (contentStudioActiveProject.clips || []).map(item => ({ ...item }))
    setContentStudioTrimHistory(history => [...history.slice(-39), historySnapshot])
    setContentStudioTrimFuture([])
    setContentStudioPreviewOutroActive(false)
    document.body.classList.add("editor-resizing")

    function applyLiveTrim(nextStart, nextEnd) {
      window.cancelAnimationFrame(contentStudioTrimFrameRef.current)

      contentStudioTrimFrameRef.current = window.requestAnimationFrame(() => {
        setContentStudioActiveProject(project => {
          if (!project) return project

          return {
            ...project,
            status: project.status === "approved" ? "edited" : project.status,
            clips: (project.clips || []).map(item =>
              item.clip_id === clip.clip_id
                ? { ...item, trim_start: nextStart, trim_end: nextEnd }
                : item
            )
          }
        })

        const video = contentStudioPreviewRef.current
        if (video) {
          video.pause()
                const previewTime = side === "left"
            ? nextStart
            : Math.min(Math.max(Number(video.currentTime || nextStart), nextStart), nextEnd)
          if (clip.blurred_side_fill) setContentStudioTwoTrackTime(previewTime)
          else video.currentTime = previewTime
        }

        const timelineStart = getContentStudioClipTimelineStart(clip.clip_id)
        const sourceTime = side === "left"
          ? nextStart
          : Math.min(Math.max(Number(contentStudioPreviewRef.current?.currentTime || nextStart), nextStart), nextEnd)
        setContentStudioPlayheadSeconds(
          Number((timelineStart + Math.max(0, sourceTime - nextStart)).toFixed(6))
        )
      })
    }

    function onPointerMove(moveEvent) {
      const deltaSeconds = (moveEvent.clientX - startX) / pixelsPerSecond

      if (timeStretchMode) {
        const desiredTimelineDuration = clampContentStudioNumber(
          originalTimelineDuration + deltaSeconds,
          Math.max(0.25, (originalEnd - originalStart) / 4),
          Math.max(0.25, (originalEnd - originalStart) / 0.25)
        )
        latestPlaybackRate = clampContentStudioNumber((originalEnd - originalStart) / desiredTimelineDuration, 0.25, 4)
        setContentStudioActiveProject(project => {
          if (!project) return project
          return {
            ...project,
            status: project.status === "approved" ? "edited" : project.status,
            clips: (project.clips || []).map(item =>
              item.clip_id === clip.clip_id ? { ...item, playback_rate: latestPlaybackRate } : item
            )
          }
        })
        const video = contentStudioPreviewRef.current
        if (video) {
          video.pause()
          video.playbackRate = latestPlaybackRate * Number(contentStudioPlaybackRate || 1)
        }
        return
      }

      if (side === "left") {
        latestStart = snapContentStudioTimeToSourceFrame(
          clampContentStudioNumber(
            originalStart + deltaSeconds,
            0,
            Math.max(0, originalEnd - minimumLength)
          ),
          clip
        )
      } else {
        latestEnd = snapContentStudioTimeToSourceFrame(
          clampContentStudioNumber(
            originalEnd + deltaSeconds,
            Math.min(duration, originalStart + minimumLength),
            duration
          ),
          clip
        )
      }

      applyLiveTrim(latestStart, latestEnd)
    }

    function finishDrag() {
      window.removeEventListener("pointermove", onPointerMove)
      window.removeEventListener("pointerup", finishDrag)
      window.removeEventListener("pointercancel", finishDrag)
      document.body.classList.remove("editor-resizing")
      window.cancelAnimationFrame(contentStudioTrimFrameRef.current)

      setContentStudioActiveProject(project => {
        if (!project) return project
        const nextProject = {
          ...project,
          clips: (project.clips || []).map(item =>
            item.clip_id === clip.clip_id
              ? { ...item, trim_start: latestStart, trim_end: latestEnd, playback_rate: latestPlaybackRate }
              : item
          )
        }
        scheduleContentStudioAutosave(nextProject)
        return nextProject
      })
    }

    window.addEventListener("pointermove", onPointerMove)
    window.addEventListener("pointerup", finishDrag)
    window.addEventListener("pointercancel", finishDrag)
  }

  function updateContentStudioClipFrame(clipId, patch, save = false) {
    setContentStudioActiveProject(project => {
      if (!project) return project
      const nextProject = {
        ...project,
        status: project.status === "approved" ? "edited" : project.status,
        clips: (project.clips || []).map(item => item.clip_id === clipId ? { ...item, ...patch } : item)
      }
      if (save) scheduleContentStudioAutosave(nextProject)
      return nextProject
    })
  }

  function startContentStudioPanCrop(clip) {
    if (!clip) return
    pauseContentStudioPreview()
    setContentStudioPreviewMenu(null)
    setContentStudioPanCropHistory([])
    setContentStudioPanCropFuture([])
    setContentStudioPanCropDraft({
      clip_id: clip.clip_id,
      frame_x: Number(clip.frame_x || 0),
      frame_y: Number(clip.frame_y || 0),
      frame_scale: Number(clip.frame_scale || 1),
      original_frame_x: Number(clip.frame_x || 0),
      original_frame_y: Number(clip.frame_y || 0),
      original_frame_scale: Number(clip.frame_scale || 1)
    })
    setContentStudioPanCropMode(true)
  }

  function cancelContentStudioPanCrop() {
    const draft = contentStudioPanCropDraft
    if (draft?.clip_id) {
      updateContentStudioClipFrame(draft.clip_id, {
        frame_x: Number(draft.original_frame_x || 0),
        frame_y: Number(draft.original_frame_y || 0),
        frame_scale: Number(draft.original_frame_scale || 1)
      }, true)
    }
    setContentStudioPreviewGuides({ horizontal: false, vertical: false })
    setContentStudioPreviewMenu(null)
    setContentStudioPanCropMode(false)
    setContentStudioPanCropDraft(null)
    setContentStudioPanCropHistory([])
    setContentStudioPanCropFuture([])
  }

  function saveContentStudioPanCrop() {
    const draft = contentStudioPanCropDraft
    if (!draft?.clip_id) return
    updateContentStudioClipFrame(draft.clip_id, {
      frame_x: Number(draft.frame_x || 0),
      frame_y: Number(draft.frame_y || 0),
      frame_scale: Number(draft.frame_scale || 1)
    }, true)
    setContentStudioPreviewGuides({ horizontal: false, vertical: false })
    setContentStudioPreviewMenu(null)
    setContentStudioPanCropMode(false)
    setContentStudioPanCropDraft(null)
    setContentStudioPanCropHistory([])
    setContentStudioPanCropFuture([])
  }

  function getContentStudioBlurCropValues(clip) {
    const detected = contentStudioSideFillCropByClip[clip?.clip_id] || {}
    return {
      left: Number(clip?.blur_crop_left_pct ?? detected.leftPct ?? 0),
      right: Number(clip?.blur_crop_right_pct ?? detected.rightPct ?? 0),
      offset: Number(clip?.blur_crop_offset_pct ?? 0)
    }
  }

  function startContentStudioBlurCrop(clip) {
    if (!clip) return
    pauseContentStudioPreview()
    setContentStudioPanCropMode(false)
    setContentStudioPanCropDraft(null)
    const values = getContentStudioBlurCropValues(clip)
    setContentStudioBlurCropDraft({
      clip_id: clip.clip_id,
      left: values.left,
      right: values.right,
      offset: values.offset
    })
    setContentStudioBlurCropMode(true)
  }

  function patchContentStudioBlurCrop(patch) {
    setContentStudioBlurCropDraft(current => current ? { ...current, ...patch } : current)
  }

  function cancelContentStudioBlurCrop() {
    setContentStudioBlurCropMode(false)
    setContentStudioBlurCropDraft(null)
  }

  function saveContentStudioBlurCrop() {
    const draft = contentStudioBlurCropDraft
    if (!draft?.clip_id) return
    updateContentStudioClip(draft.clip_id, {
      blurred_side_fill: true,
      blur_crop_left_pct: Number(draft.left || 0),
      blur_crop_right_pct: Number(draft.right || 0),
      blur_crop_offset_pct: Number(draft.offset || 0)
    })
    setContentStudioBlurCropMode(false)
    setContentStudioBlurCropDraft(null)
  }

  function beginContentStudioBlurCropHandle(event, clip, side) {
    if (!contentStudioBlurCropMode || !clip || event.button !== 0) return
    event.preventDefault()
    event.stopPropagation()
    const rect = event.currentTarget.parentElement?.getBoundingClientRect()
    const width = Math.max(1, Number(rect?.width || 1))
    const startX = event.clientX
    const draft = contentStudioBlurCropDraft?.clip_id === clip.clip_id
      ? contentStudioBlurCropDraft
      : { ...getContentStudioBlurCropValues(clip), clip_id: clip.clip_id }
    const initial = side === "left" ? Number(draft.left || 0) : Number(draft.right || 0)
    const pointerId = event.pointerId
    event.currentTarget.setPointerCapture?.(pointerId)
    const move = moveEvent => {
      if (moveEvent.pointerId !== pointerId) return
      const deltaPct = ((moveEvent.clientX - startX) / width) * 100
      const next = side === "left"
        ? clampContentStudioNumber(initial + deltaPct, 0, 42)
        : clampContentStudioNumber(initial - deltaPct, 0, 42)
      const other = side === "left" ? Number(draft.right || 0) : Number(draft.left || 0)
      patchContentStudioBlurCrop({ [side]: Number(Math.min(next, 68 - other).toFixed(2)) })
    }
    const end = () => {
      window.removeEventListener("pointermove", move)
      window.removeEventListener("pointerup", end)
      window.removeEventListener("pointercancel", end)
    }
    window.addEventListener("pointermove", move)
    window.addEventListener("pointerup", end)
    window.addEventListener("pointercancel", end)
  }

  function beginContentStudioBlurCropMove(event, clip) {
    if (!contentStudioBlurCropMode || !clip || event.button !== 0) return
    event.preventDefault()
    event.stopPropagation()
    const rect = event.currentTarget.parentElement?.getBoundingClientRect()
    const width = Math.max(1, Number(rect?.width || 1))
    const startX = event.clientX
    const initial = Number(contentStudioBlurCropDraft?.offset || 0)
    const pointerId = event.pointerId
    event.currentTarget.setPointerCapture?.(pointerId)
    const move = moveEvent => {
      if (moveEvent.pointerId !== pointerId) return
      const deltaPct = ((moveEvent.clientX - startX) / width) * 100
      patchContentStudioBlurCrop({ offset: Number(clampContentStudioNumber(initial + deltaPct, -30, 30).toFixed(2)) })
    }
    const end = () => {
      window.removeEventListener("pointermove", move)
      window.removeEventListener("pointerup", end)
      window.removeEventListener("pointercancel", end)
    }
    window.addEventListener("pointermove", move)
    window.addEventListener("pointerup", end)
    window.addEventListener("pointercancel", end)
  }

  function getContentStudioPanCropSnapshot(draft = contentStudioPanCropDraft) {
    if (!draft?.clip_id) return null
    return {
      clip_id: draft.clip_id,
      frame_x: Number(draft.frame_x || 0),
      frame_y: Number(draft.frame_y || 0),
      frame_scale: Number(draft.frame_scale || 1)
    }
  }

  function recordContentStudioPanCropStep() {
    const snapshot = getContentStudioPanCropSnapshot()
    if (!snapshot) return
    setContentStudioPanCropHistory(history => [...history.slice(-79), snapshot])
    setContentStudioPanCropFuture([])
  }

  function applyContentStudioPanCropSnapshot(snapshot) {
    if (!snapshot?.clip_id) return
    setContentStudioPanCropDraft(current => current ? { ...current, ...snapshot } : current)
    setContentStudioActiveProject(project => {
      if (!project) return project
      const nextProject = {
        ...project,
        status: project.status === "approved" ? "edited" : project.status,
        clips: (project.clips || []).map(item => item.clip_id === snapshot.clip_id ? { ...item, ...snapshot } : item)
      }
      scheduleContentStudioAutosave(nextProject)
      return nextProject
    })
  }

  function undoContentStudioPanCrop() {
    if (!contentStudioPanCropHistory.length) return
    const current = getContentStudioPanCropSnapshot()
    const previous = contentStudioPanCropHistory[contentStudioPanCropHistory.length - 1]
    setContentStudioPanCropHistory(history => history.slice(0, -1))
    if (current) setContentStudioPanCropFuture(future => [current, ...future].slice(0, 80))
    applyContentStudioPanCropSnapshot(previous)
  }

  function redoContentStudioPanCrop() {
    if (!contentStudioPanCropFuture.length) return
    const current = getContentStudioPanCropSnapshot()
    const next = contentStudioPanCropFuture[0]
    if (current) setContentStudioPanCropHistory(history => [...history.slice(-79), current])
    setContentStudioPanCropFuture(future => future.slice(1))
    applyContentStudioPanCropSnapshot(next)
  }

  function patchContentStudioPanCrop(patch) {
    const clipId = contentStudioPanCropDraft?.clip_id
    if (!clipId) return

    setContentStudioPanCropDraft(current => current ? { ...current, ...patch } : current)
    setContentStudioActiveProject(project => {
      if (!project) return project
      const nextProject = {
        ...project,
        status: project.status === "approved" ? "edited" : project.status,
        clips: (project.clips || []).map(item =>
          item.clip_id === clipId
            ? {
                ...item,
                frame_x: patch.frame_x === undefined ? Number(item.frame_x || 0) : Number(patch.frame_x || 0),
                frame_y: patch.frame_y === undefined ? Number(item.frame_y || 0) : Number(patch.frame_y || 0),
                frame_scale: patch.frame_scale === undefined ? Number(item.frame_scale || 1) : Number(patch.frame_scale || 1)
              }
            : item
        )
      }
      scheduleContentStudioAutosave(nextProject)
      return nextProject
    })
  }

  function beginContentStudioPreviewMove(event, clip) {
    if (!contentStudioPanCropMode || !clip || event.button !== 0) return
    event.preventDefault()
    event.stopPropagation()
    recordContentStudioPanCropStep()
    const draft = contentStudioPanCropDraft?.clip_id === clip.clip_id
      ? contentStudioPanCropDraft
      : { clip_id: clip.clip_id, frame_x: Number(clip.frame_x || 0), frame_y: Number(clip.frame_y || 0), frame_scale: Number(clip.frame_scale || 1) }
    const startX = event.clientX
    const startY = event.clientY
    const initialX = Number(draft.frame_x || 0)
    const initialY = Number(draft.frame_y || 0)
    const container = event.currentTarget.parentElement
    const rect = container?.getBoundingClientRect()
    const pointerId = event.pointerId
    event.currentTarget.setPointerCapture?.(pointerId)
    document.body.classList.add("editor-panning")

    const move = moveEvent => {
      if (moveEvent.pointerId !== pointerId) return
      moveEvent.preventDefault()
      const width = Math.max(1, rect?.width || 1)
      const height = Math.max(1, rect?.height || 1)
      let x = initialX + ((moveEvent.clientX - startX) / width) * 100
      let y = initialY + ((moveEvent.clientY - startY) / height) * 100
      const snap = 1.35
      const vertical = Math.abs(x) <= snap
      const horizontal = Math.abs(y) <= snap
      if (vertical) x = 0
      if (horizontal) y = 0
      setContentStudioPreviewGuides({ horizontal, vertical })
      patchContentStudioPanCrop({ frame_x: Number(x.toFixed(2)), frame_y: Number(y.toFixed(2)) })
    }

    const end = endEvent => {
      if (endEvent?.pointerId !== undefined && endEvent.pointerId !== pointerId) return
      window.removeEventListener("pointermove", move)
      window.removeEventListener("pointerup", end)
      window.removeEventListener("pointercancel", end)
      document.body.classList.remove("editor-panning")
      setContentStudioPreviewGuides({ horizontal: false, vertical: false })
    }

    window.addEventListener("pointermove", move)
    window.addEventListener("pointerup", end)
    window.addEventListener("pointercancel", end)
  }

  function beginContentStudioPreviewResize(event, clip, corner) {
    if (!contentStudioPanCropMode || !clip || event.button !== 0) return
    event.preventDefault()
    event.stopPropagation()
    recordContentStudioPanCropStep()

    const draft = contentStudioPanCropDraft?.clip_id === clip.clip_id
      ? contentStudioPanCropDraft
      : { clip_id: clip.clip_id, frame_x: Number(clip.frame_x || 0), frame_y: Number(clip.frame_y || 0), frame_scale: Number(clip.frame_scale || 1) }
    const startX = event.clientX
    const startY = event.clientY
    const initialScale = Number(draft.frame_scale || 1)
    const container = event.currentTarget.parentElement
    const rect = container?.getBoundingClientRect()
    event.currentTarget.setPointerCapture?.(event.pointerId)

    const directionX = corner.includes("right") ? 1 : -1
    const directionY = corner.includes("bottom") ? 1 : -1

    const move = moveEvent => {
      const width = Math.max(1, Number(rect?.width || 1))
      const height = Math.max(1, Number(rect?.height || 1))
      const deltaX = ((moveEvent.clientX - startX) / width) * directionX
      const deltaY = ((moveEvent.clientY - startY) / height) * directionY
      const delta = (deltaX + deltaY) * 0.85
      const nextScale = clampContentStudioNumber(initialScale + delta, 0.5, 3)
      patchContentStudioPanCrop({ frame_scale: Number(nextScale.toFixed(3)) })
    }

    const end = () => {
      window.removeEventListener("pointermove", move)
      window.removeEventListener("pointerup", end)
      window.removeEventListener("pointercancel", end)
    }

    window.addEventListener("pointermove", move)
    window.addEventListener("pointerup", end)
    window.addEventListener("pointercancel", end)
  }

  function handleContentStudioPreviewWheel(event, clip) {
    if (!contentStudioPanCropMode || !clip) return
    event.preventDefault()
    event.stopPropagation()
    recordContentStudioPanCropStep()
    const current = Number(contentStudioPanCropDraft?.frame_scale || clip.frame_scale || 1)
    const next = clampContentStudioNumber(current + (event.deltaY < 0 ? 0.05 : -0.05), 0.5, 3)
    patchContentStudioPanCrop({ frame_scale: Number(next.toFixed(2)) })
  }

  function resetContentStudioPreviewTransform(clip) {
    if (!clip) return
    if (contentStudioPanCropMode) {
      recordContentStudioPanCropStep()
      patchContentStudioPanCrop({ frame_x: 0, frame_y: 0, frame_scale: 1 })
    } else {
      updateContentStudioClipFrame(clip.clip_id, { frame_x: 0, frame_y: 0, frame_scale: 1 }, true)
    }
    setContentStudioPreviewMenu(null)
  }

  function openContentStudioPreviewMenu(event, clip) {
    if (!contentStudioPanCropMode || !clip) return
    event.preventDefault()
    const containerRect = event.currentTarget.parentElement?.getBoundingClientRect()
    setContentStudioPreviewMenu({
      clipId: clip.clip_id,
      x: Math.max(8, event.clientX - Number(containerRect?.left || 0)),
      y: Math.max(8, event.clientY - Number(containerRect?.top || 0))
    })
  }

  useEffect(() => {
    if (contentStudioActiveProject) {
      contentStudioLatestProjectRef.current = contentStudioActiveProject
      storeContentStudioLocalDraft(contentStudioActiveProject)
    }
  }, [contentStudioActiveProject])

  useEffect(() => {
    const flushLatestProject = () => {
      window.clearTimeout(contentStudioAutosaveTimerRef.current)
      const latest = contentStudioLatestProjectRef.current
      if (latest?.project_id) persistContentStudioProject(latest, { keepalive: true })
    }
    window.addEventListener("pagehide", flushLatestProject)
    window.addEventListener("beforeunload", flushLatestProject)
    return () => {
      window.removeEventListener("pagehide", flushLatestProject)
      window.removeEventListener("beforeunload", flushLatestProject)
    }
  }, [])

  useEffect(() => {
    return () => {
      stopContentStudioFrameHold()
      window.clearTimeout(contentStudioAutosaveTimerRef.current)
      if (contentStudioRenderPollRef.current) {
        clearInterval(contentStudioRenderPollRef.current)
        contentStudioRenderPollRef.current = null
      }
    }
  }, [])

  useEffect(() => {
    function handleEditorKeyboard(event) {
      if (!contentStudioActiveProject || tab !== "contentStudio") return

      const tag = String(event.target?.tagName || "").toLowerCase()
      if (["input", "textarea", "select"].includes(tag)) return

      if (event.code === "Space") {
        event.preventDefault()
        if (contentStudioPreviewPlaying) pauseContentStudioPreview()
        else playContentStudioPreview()
      }

      const activeKeyboardClip = (contentStudioActiveProject.clips || []).find(
        clip => clip.clip_id === contentStudioSelectedClipId
      ) || (contentStudioActiveProject.clips || [])[0]

      if (event.key === "ArrowLeft" && activeKeyboardClip) {
        event.preventDefault()
        seekContentStudioSelectedClipRelative(
          getContentStudioPreviewRelativeTime(activeKeyboardClip) - (event.shiftKey ? 1 : getContentStudioFrameDuration(activeKeyboardClip))
        )
      }

      if (event.key === "ArrowRight" && activeKeyboardClip) {
        event.preventDefault()
        seekContentStudioSelectedClipRelative(
          getContentStudioPreviewRelativeTime(activeKeyboardClip) + (event.shiftKey ? 1 : getContentStudioFrameDuration(activeKeyboardClip))
        )
      }

      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "z") {
        event.preventDefault()
        if (contentStudioPanCropMode) {
          if (event.shiftKey) redoContentStudioPanCrop()
          else undoContentStudioPanCrop()
        } else if (event.shiftKey) redoContentStudioTrim()
        else undoContentStudioTrim()
      }

      if (!event.ctrlKey && !event.metaKey && event.key.toLowerCase() === "s" && activeKeyboardClip) {
        event.preventDefault()
        splitContentStudioClip(activeKeyboardClip.clip_id)
      }

      if ((event.key === "Delete" || event.key === "Backspace") && !event.ctrlKey && !event.metaKey && contentStudioSelectedClipId) {
        event.preventDefault()
        removeContentStudioClipFromTimeline(contentStudioSelectedClipId)
      }

      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "c" && contentStudioSelectedClipId) {
        event.preventDefault()
        copyContentStudioSelectedClip()
      }

      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "v") {
        event.preventDefault()
        pasteContentStudioClipboardClip()
      }

      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "x" && contentStudioSelectedClipId) {
        event.preventDefault()
        removeContentStudioClipFromTimeline(contentStudioSelectedClipId)
      }
    }

    window.addEventListener("keydown", handleEditorKeyboard)
    return () => window.removeEventListener("keydown", handleEditorKeyboard)
  }, [
    tab,
    contentStudioActiveProject,
    contentStudioPreviewPlaying,
    contentStudioSelectedClipId,
    contentStudioPlayheadSeconds,
    contentStudioTrimHistory,
    contentStudioTrimFuture
  ])

  useEffect(() => {
    if (!contentStudioPreviewPlaying || !contentStudioActiveProject) {
      stopContentStudioPlayheadSync()
      return undefined
    }

    const video = contentStudioPreviewRef.current
    const activeClip = getContentStudioSelectedClip()

    if (video && activeClip) {
      startContentStudioPlayheadSync(video, activeClip)
    }

    return () => stopContentStudioPlayheadSync()
  }, [
    contentStudioPreviewPlaying,
    contentStudioActiveProject?.project_id,
    contentStudioSelectedClipId,
    contentStudioTimelineZoom
  ])

  useEffect(() => {
    const projectId = contentStudioActiveProject?.project_id
    const rendering = contentStudioActiveProject?.render_status === "rendering"

    if (!projectId || !rendering || !contentStudioActionModalOpen) {
      setContentStudioRenderPreviewReady(false)
      setContentStudioRenderPreviewUrl("")
      return undefined
    }

    setContentStudioRenderPreviewReady(false)
    setContentStudioRenderPreviewNonce(Date.now())
    return undefined
  }, [
    contentStudioActiveProject?.project_id,
    contentStudioActiveProject?.render_status,
    contentStudioActionModalOpen
  ])

  useEffect(() => {
    const projectId = contentStudioActiveProject?.project_id
    const rendering = contentStudioActiveProject?.render_status === "rendering"

    if (!projectId || !rendering || !contentStudioActionModalOpen || !contentStudioRenderPreviewNonce) {
      return undefined
    }

    let canceled = false
    let nextTimer = null
    const candidateUrl = `${API}/content-studio/project/${projectId}/render-preview?t=${contentStudioRenderPreviewNonce}`
    const candidate = new Image()

    const scheduleNext = delay => {
      if (canceled) return
      nextTimer = window.setTimeout(() => {
        if (!canceled) setContentStudioRenderPreviewNonce(Date.now())
      }, delay)
    }

    candidate.onload = () => {
      if (canceled) return
      // Only replace the visible frame after the next JPEG has fully decoded.
      // A missing/in-progress frame can therefore never replace the last good
      // frame with the browser's broken-image icon.
      setContentStudioRenderPreviewUrl(candidateUrl)
      setContentStudioRenderPreviewReady(true)
      scheduleNext(140)
    }

    candidate.onerror = () => {
      // Keep the last successful frame visible and calmly try the next snapshot.
      scheduleNext(contentStudioRenderPreviewReady ? 180 : 350)
    }

    candidate.src = candidateUrl

    return () => {
      canceled = true
      candidate.onload = null
      candidate.onerror = null
      if (nextTimer) window.clearTimeout(nextTimer)
    }
  }, [
    API,
    contentStudioActiveProject?.project_id,
    contentStudioActiveProject?.render_status,
    contentStudioActionModalOpen,
    contentStudioRenderPreviewNonce,
    contentStudioRenderPreviewReady
  ])

  function isContentStudioPreviewConfirmed(project = contentStudioActiveProject) {
    if (!project?.project_id) return false
    return !!contentStudioPreviewConfirmed[project.project_id] || !!project.preview_confirmed
  }

  function confirmContentStudioPreview() {
    if (!contentStudioActiveProject?.project_id) return

    if (!contentStudioActiveProject?.rendered_video?.preview_url) {
      showCourtVisionDialog("Render the final MP4 first, then confirm the preview.")
      return
    }

    fetch(`${API}/content-studio/project/${contentStudioActiveProject.project_id}/confirm-preview`, {
      method: "PUT"
    })
      .then(r => r.json())
      .then(data => {
        if (!data.confirmed) {
          showCourtVisionDialog(data.message || "Preview could not be confirmed yet.")
          return
        }

        setContentStudioActiveProject(data.project || contentStudioActiveProject)
        setContentStudioPreviewConfirmed(prev => ({
          ...prev,
          [contentStudioActiveProject.project_id]: true
        }))
        loadContentStudioData()
        showCourtVisionDialog("Final preview approved. Use the separate Upload to YouTube button when you are ready.", {
          title: "Preview Approved",
          resolution: "Close this message to keep reviewing the project, or click Upload to YouTube from the Finish Project window."
        })
      })
      .catch(err => showCourtVisionDialog("Preview confirmation failed: " + err.message))
  }

  function pollContentStudioRender(projectId) {
    if (contentStudioRenderPollRef.current) {
      clearInterval(contentStudioRenderPollRef.current)
      contentStudioRenderPollRef.current = null
    }

    let consecutiveErrors = 0
    let requestInFlight = false

    const checkStatus = () => {
      if (requestInFlight) return
      requestInFlight = true

      fetch(`${API}/content-studio/project/${projectId}/render-status`, {
        cache: "no-store"
      })
        .then(async response => {
          let data = null

          try {
            data = await response.json()
          } catch {
            data = null
          }

          if (!response.ok || data?.found === false) {
            throw new Error(
              data?.message ||
              `Render status temporarily unavailable (${response.status})`
            )
          }

          consecutiveErrors = 0

          const backendProgress = Number(
            data?.job?.progress ??
            data?.project?.render_progress ??
            0
          )

          const safeProgress = Math.max(
            1,
            Math.min(
              100,
              Number.isFinite(backendProgress) ? backendProgress : 1
            )
          )

          const rawStage =
            data?.job?.stage ||
            data?.project?.render_stage ||
            "Rendering final video"
          const stage = String(rawStage).replace(/\s*[—-]\s*\d{1,3}%\s*$/, "").trim() || "Rendering final video"

          setContentStudioRenderProgress(previous =>
            safeProgress >= 100
              ? 100
              : Math.max(Number(previous || 1), safeProgress)
          )
          setContentStudioRenderStage(stage)
          const backendEta = Number(data?.job?.eta_seconds)
          const startedAt = Number(contentStudioRenderStartedAtRef.current || 0)
          let targetEta = null
          if (Number.isFinite(backendEta) && backendEta >= 0 && safeProgress < 100) {
            targetEta = backendEta
          } else if (safeProgress < 100 && Number.isFinite(Number(contentStudioRenderEtaTargetRef.current))) {
            const elapsedSeconds = startedAt > 0 ? Math.max(0, (Date.now() - startedAt) / 1000) : 0
            targetEta = Math.max(1, Number(contentStudioRenderEtaTargetRef.current) - elapsedSeconds)
          } else if (safeProgress >= 100) {
            targetEta = 0
          }

          if (targetEta !== null) {
            contentStudioRenderEtaTargetRef.current = targetEta
            setContentStudioRenderEtaSeconds(previous => {
              if (safeProgress >= 100) return 0
              if (previous === null || !Number.isFinite(Number(previous))) return Math.round(targetEta)
              const current = Number(previous)
              const maxDrop = Math.max(1, Math.round(current * 0.035))
              const maxRise = Math.max(1, Math.round(current * 0.012))
              const bounded = Math.max(current - maxDrop, Math.min(current + maxRise, targetEta))
              return Math.max(0, Math.round(bounded))
            })
          }

          if (data?.project) {
            setContentStudioActiveProject(previous => ({
              ...(previous || {}),
              ...data.project,
              render_status:
                data?.job?.status === "complete" || safeProgress >= 100
                  ? "rendered"
                  : data?.job?.status === "failed"
                    ? "failed"
                    : "rendering",
              render_progress: safeProgress,
              render_stage: stage
            }))
          }

          const complete =
            data?.job?.status === "complete" ||
            data?.project?.render_status === "rendered" ||
            safeProgress >= 100

          if (complete) {
            if (contentStudioRenderPollRef.current) {
              clearInterval(contentStudioRenderPollRef.current)
              contentStudioRenderPollRef.current = null
            }

            setContentStudioRenderProgress(100)
            setContentStudioRenderStage("Render complete")
            setContentStudioRenderEtaSeconds(0)
            setContentStudioSelectedClipId(
              data.project?.clips?.[0]?.clip_id ||
              contentStudioSelectedClipId
            )
            loadContentStudioData()
            return
          }

          if (
            data?.job?.status === "failed" ||
            data?.project?.render_status === "failed"
          ) {
            if (contentStudioRenderPollRef.current) {
              clearInterval(contentStudioRenderPollRef.current)
              contentStudioRenderPollRef.current = null
            }

            const failureMessage =
              stage ||
              data?.project?.render_error?.message ||
              "Unknown FFmpeg error"

            setContentStudioRenderStage(`Render failed: ${failureMessage}`)
          }
        })
        .catch(error => {
          consecutiveErrors += 1
          console.warn("Render status poll retry", consecutiveErrors, error)

          // Keep the render modal alive and preserve its last real percentage.
          // A long 60/120 FPS interpolation job can make the backend briefly busy.
          setContentStudioRenderStage(previous => {
            const current = String(previous || "").trim()

            if (
              current &&
              !current.startsWith("Reconnecting to render status")
            ) {
              return current
            }

            return `Reconnecting to render status… attempt ${consecutiveErrors}`
          })
        })
        .finally(() => {
          requestInFlight = false
        })
    }

    checkStatus()
    contentStudioRenderPollRef.current = setInterval(checkStatus, 900)
  }

  async function renderContentStudioProject() {
    if (!contentStudioActiveProject) return

    // Freeze and save the newest complete editor state before rendering. The
    // previous custom render-save payload omitted clip-specific effects such
    // as blurred_side_fill, which silently reset them immediately before the
    // backend render started. Waiting for the serialized save chain also keeps
    // the latest trim endpoint, so the outro cannot start from stale timing.
    const latestProject = contentStudioLatestProjectRef.current || contentStudioActiveProject
    const projectForRender = {
      ...latestProject,
      clips: (latestProject.clips || []).map(clip => ({ ...clip })),
      render_settings: {
        output_fps: Number(contentStudioOutputFps),
        interpolation_mode: contentStudioInterpolationMode
      }
    }

    contentStudioLatestProjectRef.current = projectForRender
    const initialEta = estimateContentStudioRenderSeconds(projectForRender, contentStudioOutputFps, contentStudioInterpolationMode)
    contentStudioRenderStartedAtRef.current = Date.now()
    contentStudioRenderEtaTargetRef.current = initialEta
    setContentStudioRenderProgress(1)
    setContentStudioRenderStage("Preparing Render")
    setContentStudioRenderEtaSeconds(initialEta)
    setContentStudioRenderPreviewReady(false)
    setContentStudioRenderPreviewNonce(Date.now())

    try {
      window.clearTimeout(contentStudioAutosaveTimerRef.current)
      await persistContentStudioProject(projectForRender, { keepalive: false })
      await contentStudioSaveChainRef.current.catch(() => null)

      setContentStudioActiveProject(previous => ({
        ...(previous || projectForRender),
        ...projectForRender,
        render_status: "rendering",
        render_progress: 1
      }))
      setContentStudioRenderStage("Starting render")

      const renderResponse = await fetch(`${API}/content-studio/project/${projectForRender.project_id}/render`, {
        method: "POST"
      })
      const renderData = await renderResponse.json()

      if (!renderResponse.ok || renderData.ok === false) {
        throw new Error(renderData.message || "Render could not start.")
      }

      setContentStudioActiveProject(previous => ({
        ...(previous || projectForRender),
        ...(renderData.project || {}),
        render_status: "rendering",
        render_progress: Number(renderData?.job?.progress || 1),
        render_stage: renderData?.job?.stage || "Starting render"
      }))
      const initialBackendEta = Number(renderData?.job?.eta_seconds)
      if (Number.isFinite(initialBackendEta) && initialBackendEta > 0) {
        contentStudioRenderEtaTargetRef.current = initialBackendEta
        setContentStudioRenderEtaSeconds(Math.round(initialBackendEta))
      }
      setContentStudioActionModalOpen(true)
      pollContentStudioRender(projectForRender.project_id)
    } catch (error) {
      setContentStudioRenderProgress(0)
      setContentStudioRenderStage("")
      setContentStudioRenderEtaSeconds(null)
      showCourtVisionDialog(`Render failed: ${error.message}`)
    }
  }


  async function loadContentStudioYoutubePlaylists({ allowReconnect = true } = {}) {
    setContentStudioYoutubePlaylistsLoading(true)
    setContentStudioYoutubePlaylistsError("")

    try {
      const response = await fetch(`${API}/content-studio/youtube/playlists`, {
        cache: "no-store"
      })

      const data = await response.json().catch(() => null)

      if (!response.ok || !data?.ok) {
        const message = data?.message || data?.detail || "YouTube playlists could not be loaded."
        const technical = data?.technical_detail || ""
        const authProblem = /invalid_grant|oauth|token|permission|unauthorized|credentials/i.test(
          `${message} ${technical}`
        )

        if (authProblem && allowReconnect) {
          showCourtVisionDialog(
            "Your YouTube authorization needs to be refreshed. Google sign-in will open automatically.",
            {
              title: "Reconnect YouTube",
              type: "warning",
              resolution: "Complete Google sign-in in the browser window. CourtVision will reload your playlists afterward.",
              technicalDetail: technical
            }
          )

          const reconnectResponse = await fetch(`${API}/content-studio/youtube/reconnect`, {
            method: "POST",
            cache: "no-store"
          })
          const reconnectData = await reconnectResponse.json().catch(() => null)

          if (!reconnectResponse.ok || !reconnectData?.ok) {
            throw Object.assign(
              new Error(reconnectData?.message || "CourtVision could not reset YouTube authorization."),
              {
                resolution: reconnectData?.resolution,
                technicalDetail: reconnectData?.technical_detail
              }
            )
          }

          setCourtVisionDialog(null)

          // Calling the playlists route again starts the Google OAuth local
          // browser flow. The request completes after sign-in succeeds.
          return await loadContentStudioYoutubePlaylists({ allowReconnect: false })
        }

        throw Object.assign(new Error(message), {
          resolution: data?.resolution,
          technicalDetail: technical
        })
      }

      const playlists = Array.isArray(data.playlists) ? data.playlists : []
      setContentStudioYoutubePlaylists(playlists)

      if (playlists.length === 0) {
        setContentStudioYoutubePlaylistsError(
          "No owned YouTube playlists were found for this channel."
        )
      }

      return playlists
    } catch (error) {
      console.error("YouTube playlist loading failed", error)
      setContentStudioYoutubePlaylists([])
      setContentStudioYoutubePlaylistsError(
        error.message || "YouTube authorization needs attention."
      )

      showCourtVisionDialog(
        error.message || "YouTube playlists could not be loaded.",
        {
          title: "Playlist Connection Failed",
          type: "error",
          resolution:
            error.resolution ||
            "Click Reconnect YouTube, complete Google sign-in, and retry.",
          technicalDetail: error.technicalDetail || ""
        }
      )

      return []
    } finally {
      setContentStudioYoutubePlaylistsLoading(false)
    }
  }

  async function generateContentStudioMetadataSuggestion() {
    if (!contentStudioActiveProject?.project_id) return
    const cleanPlayer = String(contentStudioPlayerName || "").trim()
    const cleanHappening = String(contentStudioClipHappening || "").trim()
    if (!cleanPlayer && !cleanHappening) {
      showCourtVisionDialog("Enter the player name or describe what happens in the clip first.", { title: "More Information Needed", type: "warning", resolution: "Add at least one of the two fields, then generate again." })
      return
    }
    try {
      const response = await fetch(`${API}/content-studio/project/${contentStudioActiveProject.project_id}/metadata-suggestion`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ clip_happening: cleanHappening, player_name: cleanPlayer, video_type: contentStudioActiveProject.project_type })
      })
      const data = await response.json().catch(() => null)
      if (!response.ok || !data?.ok) {
        throw Object.assign(new Error(data?.message || `Metadata request failed (${response.status})`), { resolution: data?.resolution, technicalDetail: data?.technical_detail })
      }
      setContentStudioActiveProject(data.project || contentStudioActiveProject)
      showCourtVisionDialog("Title, description, and 500-character tags were generated successfully.", { title: "Metadata Ready", type: "success", resolution: "Review and edit the generated fields before uploading." })
    } catch (error) {
      showCourtVisionDialog(error.message || "Metadata generation failed.", { title: "Metadata Generation Failed", type: "error", resolution: error.resolution || "Restart the backend so the metadata route is registered, then retry.", technicalDetail: error.technicalDetail || "" })
    }
  }

  function uploadContentStudioThumbnail() {
    if (!contentStudioThumbnailFile || !contentStudioActiveProject?.project_id) {
      return Promise.resolve(null)
    }

    const form = new FormData()
    form.append("thumbnail", contentStudioThumbnailFile)

    return fetch(`${API}/content-studio/project/${contentStudioActiveProject.project_id}/thumbnail`, {
      method: "POST",
      body: form
    })
      .then(response => response.json())
      .then(data => {
        if (!data.ok) throw new Error(data.detail || data.message || "Thumbnail upload failed")
        setContentStudioActiveProject(data.project || contentStudioActiveProject)
        return data
      })
  }

  function uploadContentStudioToYoutube() {
    if (!contentStudioActiveProject?.project_id) return
    const draft = getContentStudioDraft()

    if (!draft?.title?.trim()) {
      showCourtVisionDialog("Add a YouTube title first.")
      return
    }

    const tagValidation = sanitizeYouTubeTags(draft.tags || "")
    if (!tagValidation.valid) {
      showCourtVisionDialog("The Tags field exceeds YouTube's safe keyword limit.", {
        title: "YouTube Tags Need Fixing",
        type: "warning",
        code: "youtube_invalid_tags",
        resolution: "Regenerate the tags or remove lower-priority keywords, then retry the upload."
      })
      return
    }

    setContentStudioYoutubeUploading(true)
    setContentStudioYoutubeResult(null)

    Promise.resolve()
      .then(() => uploadContentStudioThumbnail())
      .then(() => {
        const form = new FormData()
        form.append("title", draft.title)
        form.append("description", draft.description || "")
        form.append("tags", tagValidation.csv)
        form.append("privacy_status", contentStudioYoutubePrivacy)
        form.append("publish_at", contentStudioPublishAt || "")
        form.append("playlist_ids", JSON.stringify(contentStudioSelectedPlaylists))

        return fetch(`${API}/content-studio/project/${contentStudioActiveProject.project_id}/youtube/upload`, {
          method: "POST",
          body: form
        })
      })
      .then(response => response.json())
      .then(data => {
        if (!data.ok) throw Object.assign(new Error(data.message || "YouTube upload failed"), {
          resolution: data.resolution,
          technicalDetail: data.technical_detail,
          code: data.code
        })
        setContentStudioYoutubeResult(data.result)
        setContentStudioActiveProject(data.project || contentStudioActiveProject)
        loadContentStudioData()
        loadContentStudioTrash()
      })
      .catch(error => {
        const invalidTags = error.code === "youtube_invalid_tags" || /invalidtags|invalid video keywords|invalid tags/i.test(
          `${error.message || ""} ${error.technicalDetail || ""}`
        )
        showCourtVisionDialog(error.message || "YouTube upload failed.", {
          title: invalidTags ? "YouTube Tags Need Fixing" : "YouTube Upload Failed",
          type: invalidTags ? "warning" : "error",
          code: invalidTags ? "youtube_invalid_tags" : (error.code || ""),
          resolution: invalidTags
            ? "Review or regenerate the Tags field and retry. Reconnecting YouTube will not fix invalid video keywords."
            : (error.resolution || getCourtVisionResolution(error.message)),
          technicalDetail: error.technicalDetail || ""
        })
      })
      .finally(() => setContentStudioYoutubeUploading(false))
  }

  function stopContentStudioRender() {
    const projectId = contentStudioActiveProject?.project_id
    if (!projectId) return

    fetch(`${API}/content-studio/project/${projectId}/render/cancel`, {
      method: "POST"
    })
      .then(response => response.json())
      .then(data => {
        if (data?.project) setContentStudioActiveProject(data.project)
        setContentStudioRenderStage("Render canceled by user")
        if (contentStudioRenderPollRef.current) {
          clearInterval(contentStudioRenderPollRef.current)
          contentStudioRenderPollRef.current = null
        }
      })
      .catch(error => showCourtVisionDialog(`Could not stop render: ${error.message}`))
  }

  function autoDetectContentStudioClips() {
    if (!contentStudioActiveProject?.project_id) {
      showCourtVisionDialog("Open a Content Studio project first.")
      return
    }

    const proceed = confirm(
      "Create 10 rough editable clip slots from your long source video? You can still trim, rename, delete, and drag them into final order after."
    )

    if (!proceed) return

    fetch(`${API}/content-studio/project/${contentStudioActiveProject.project_id}/auto-detect-clips`, {
      method: "POST"
    })
      .then(async r => {
        const data = await r.json()

        if (!r.ok || data.ok === false) {
          showCourtVisionDialog("Clip detection failed: " + JSON.stringify(data.message || data))
          return
        }

        setContentStudioActiveProject(data.project || contentStudioActiveProject)
        setContentStudioSelectedClipId(data.project?.clips?.[0]?.clip_id || contentStudioSelectedClipId)
        setContentStudioPlayheadSeconds(0)
        loadContentStudioData()
        showCourtVisionDialog("10 rough clip slots created. Now trim each dunk exactly and drag them into your Top 10 order.")
      })
      .catch(err => showCourtVisionDialog("Clip detection failed: " + err.message))
  }

  function renderContentStudioSolos() {
    if (!contentStudioActiveProject?.project_id) {
      showCourtVisionDialog("Open a Content Studio project first.")
      return
    }

    const proceed = confirm(
      "Export every clip as its own solo highlight with 0.1 second fades and your outro PNG?"
    )

    if (!proceed) return

    const draft = getContentStudioDraft()

    fetch(`${API}/content-studio/project/${contentStudioActiveProject.project_id}/edit`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        project_name: contentStudioActiveProject.project_name,
        clips: (contentStudioActiveProject.clips || []).map((clip, index) => ({
          clip_id: clip.clip_id,
          order: index + 1,
          title: clip.title,
          trim_start: Number(clip.trim_start || 0),
          trim_end: Number(clip.trim_end || 0),
          duration_seconds: Number(clip.duration_seconds || 0),
          selected_for_top10: !!clip.selected_for_top10,
          frame_x: Number(clip.frame_x || 0),
          frame_y: Number(clip.frame_y || 0),
          frame_scale: Number(clip.frame_scale || 1),
          source_fps: Number(clip.source_fps || 0),
          muted: !!clip.muted,
          playback_rate: getContentStudioClipPlaybackRate(clip)
        })),
        top10_draft: contentStudioActiveProject.project_type === "top10" ? draft : null,
        solo_draft: contentStudioActiveProject.project_type === "solo" ? draft : null
      })
    })
      .then(async saveResponse => {
        const savedData = await saveResponse.json()

        if (!saveResponse.ok || savedData.found === false) {
          showCourtVisionDialog("Project save before solo export failed: " + JSON.stringify(savedData))
          return null
        }

        setContentStudioActiveProject({
          ...savedData.project,
          solo_export_status: "exporting"
        })

        return fetch(`${API}/content-studio/project/${contentStudioActiveProject.project_id}/render-solos`, {
          method: "POST"
        })
      })
      .then(async exportResponse => {
        if (!exportResponse) return

        const exportData = await exportResponse.json()

        if (!exportResponse.ok || exportData.ok === false) {
          setContentStudioActiveProject(exportData.project || contentStudioActiveProject)
          showCourtVisionDialog("Solo export failed: " + JSON.stringify(exportData.message || exportData.result || exportData))
          return
        }

        setContentStudioActiveProject(exportData.project)
        loadContentStudioData()
        showCourtVisionDialog(`Solo export finished. ${exportData.solo_exports?.filter(item => item.ok).length || 0} clips are ready.`)
      })
      .catch(err => showCourtVisionDialog("Solo export failed: " + err.message))
  }

function syncYouTubeRevenue(syncType = "daily") {
    const isFull = syncType === "full"

    if (isFull) {
      const proceed = confirm(
        "Run a full YouTube revenue sync? This can take a while, but it should pull all-time YouTube Studio estimated revenue/RPM history into CourtVision."
      )

      if (!proceed) return
    }

    setYoutubeRevenueSyncing(true)

    const url = isFull
      ? `${API}/revenue/youtube/sync?sync_type=full&start_date=2022-10-09`
      : `${API}/revenue/youtube/sync?sync_type=daily`

    fetch(url, {
      method: "POST"
    })
      .then(async r => {
        const data = await r.json()

        if (!r.ok || data.ok === false) {
          showCourtVisionDialog("YouTube revenue sync failed: " + JSON.stringify(data.message || data))
          return
        }

        setYoutubeRevenueStatus(data.status || null)
        loadRevenueData()
        loadData()

        showCourtVisionDialog(
          `YouTube revenue sync complete. Channel rows: ${data.channel_rows_saved}. Video rows: ${data.video_rows_saved}.`
        )
      })
      .catch(err => {
        showCourtVisionDialog("YouTube revenue sync failed: " + err.message)
      })
      .finally(() => setYoutubeRevenueSyncing(false))
  }

